const EQUIPE_ETATS = {
  active: ['Actif', 'badge-success'],
  pending: ['Jamais venu', 'badge-neutral'],
  blocked: ['Bloqué', 'badge-danger']
};

function equipeSession() {
  return normalizeStaffSession(state.staffAuthSession) || readStoredStaffSession() || {};
}

function equipeEstProprietaire() {
  return canUseStaffPermission('platform.admin');
}

// La Direction ou le propriétaire de la plateforme donnent le rôle Direction
// (le serveur refuse tous les autres : peutDonnerLeRole, api/staff-auth.js).
function equipePeutDonnerDirection() {
  const session = equipeSession();
  return Boolean(session.role?.locked) || equipeEstProprietaire();
}

// Les droits d'un rôle, verrouillé compris (la Direction a tout dans son centre).
function equipeDroitsDuRole(role) {
  if (!role) return new Set();
  if (role.locked) return new Set(getStaffPermissionKeys());
  return new Set(Array.isArray(role.permissions) ? role.permissions : []);
}

// Une page s'ouvre-t-elle avec ces droits ? La même règle que la console
// (canUseStaffPage), appliquée à un rôle au lieu de la session.
function equipePageOuverte(page, droits, verrouille) {
  const requises = STAFF_PAGE_PERMISSION_MAP[page];
  if (!requises) return false;
  return requises.some(permission => (PLATFORM_STAFF_PERMISSIONS.has(permission) ? droits.has(permission) : (verrouille || droits.has(permission))));
}

function equipeEcranOuvert(ecran, droits, verrouille) {
  if (ecran.page) return equipePageOuverte(ecran.page, droits, verrouille);
  if (ecran.ouvre) return verrouille || droits.has(ecran.ouvre[0]);
  return (ecran.droits || []).some(([permission]) => verrouille || droits.has(permission));
}

// Le menu de gauche tel qu'une personne de ce rôle le voit : la même liste que
// la vraie barre (window.FGX_STAFF_MENU, assets/staff-menu.js), la même règle.
function equipeMenuDuRole(role) {
  const droits = equipeDroitsDuRole(role);
  const verrouille = Boolean(role && role.locked);
  const peut = permission => !permission || (PLATFORM_STAFF_PERMISSIONS.has(permission) ? droits.has(permission) : (verrouille || droits.has(permission)));
  const page = key => {
    if (key === 'bowling' || key === 'laser' || key === 'complete') return 'planning';
    if (String(key || '').startsWith('emails-')) return 'emails';
    return key;
  };
  const sections = Array.isArray(window.FGX_STAFF_MENU) ? window.FGX_STAFF_MENU : [];
  return sections.map(section => {
    const items = (section.items || []).map(item => {
      if (item.children) {
        const enfants = item.children.filter(child => equipePageOuverte(page(child.key), droits, verrouille) && peut(child.permission));
        if (!enfants.length && !item.landing) return null;
        if (item.landing && !equipePageOuverte(page(item.key), droits, verrouille)) return null;
        return { label: item.label, enfants: enfants.map(child => child.label) };
      }
      return equipePageOuverte(page(item.key), droits, verrouille) ? { label: item.label, enfants: [] } : null;
    }).filter(Boolean);
    return items.length ? { titre: section.title, items } : null;
  }).filter(Boolean);
}

// Les écrans de la carte qui restent fermés à ce rôle.
function equipeEcransFermes(role) {
  const droits = equipeDroitsDuRole(role);
  const verrouille = Boolean(role && role.locked);
  return CARTE_DES_DROITS.flatMap(groupe => groupe.ecrans)
    .filter(ecran => !equipeEcranOuvert(ecran, droits, verrouille))
    .map(ecran => ecran.nom);
}

function equipeQuand(valeur) {
  if (!valeur) return '';
  const date = new Date(valeur);
  if (Number.isNaN(date.getTime())) return '';
  const heure = date.toLocaleTimeString('fr-BE', { hour: '2-digit', minute: '2-digit' });
  const jour = d => d.toLocaleDateString('fr-BE');
  const hier = new Date(Date.now() - 86400000);
  if (jour(date) === jour(new Date())) return `aujourd’hui à ${heure}`;
  if (jour(date) === jour(hier)) return `hier à ${heure}`;
  return `le ${date.toLocaleDateString('fr-BE', { day: '2-digit', month: '2-digit' })}`;
}

function equipeNomDuCentre(access, centerId) {
  const centre = (access.entreprise || []).find(item => item.id === centerId);
  const nom = (centre && centre.name) || centerId;
  // « Fun Galaxy Gembloux » se dit « Gembloux » sur cette page : l'entreprise
  // est la même partout.
  return String(nom).replace(/^Fun Galaxy\s+/i, '').replace(/\s+Centre$/i, '') || nom;
}

// Les centres d'une personne, celui qu'on regarde en premier.
function equipeCentresDe(member) {
  const ici = (state.staffAccessControl && state.staffAccessControl.centerId) || getCurrentStaffCenterId();
  const centres = Array.isArray(member.centres) && member.centres.length
    ? member.centres.slice()
    : [{ centerId: member.centerId, memberId: member.id, roleId: member.roleId, status: member.status }];
  return centres.sort((a, b) => (a.centerId === ici ? -1 : 0) - (b.centerId === ici ? -1 : 0) || String(a.centerId).localeCompare(String(b.centerId)));
}

// La personne, tous centres confondus : venue dès qu'une de ses fiches l'a été
// (une session ne rafraîchit que la fiche de son centre de connexion).
function equipeVuDeLaPersonne(member) {
  const dates = [member.lastSeen, ...equipeCentresDe(member).map(centre => centre.lastSeen)]
    .filter(Boolean).map(valeur => new Date(valeur).getTime()).filter(Number.isFinite);
  return dates.length ? new Date(Math.max(...dates)).toISOString() : '';
}

function equipeEtatDeLaPersonne(member) {
  if (member.status === 'blocked') return 'blocked';
  if (equipeVuDeLaPersonne(member) || equipeCentresDe(member).some(centre => centre.status === 'active')) return 'active';
  return 'pending';
}

function equipeEstSoi(member) {
  const session = equipeSession();
  const ids = new Set([session.member && session.member.id].filter(Boolean));
  return equipeCentresDe(member).some(centre => ids.has(centre.memberId));
}

function equipeRoleDe(access, member) {
  return (access.roles || []).find(role => role.id === member.roleId) || { id: member.roleId, name: member.roleId };
}

function equipePersonnes(access) {
  return getVisibleStaffAccessMembers(access);
}

function equipeMembreChoisi(access) {
  const personnes = equipePersonnes(access);
  return personnes.find(member => member.id === access.selectedMemberId) || personnes.find(member => !member.partage) || personnes[0] || null;
}

// LE JOURNAL DE L EQUIPE EST AU FONDATEUR SEUL (Ansar, 2026-11-13 : « ça c est un truc que moi seul dois
// avoir »). Le serveur ne l envoie qu a lui (listAccessControl) ; l onglet ne s ouvre que pour lui.
function equipeOngletsPermis() {
  return equipeEstProprietaire() ? ['personnes', 'roles', 'journal'] : ['personnes', 'roles'];
}

function equipeOnglet() {
  return equipeOngletsPermis().includes(state.equipeOnglet) ? state.equipeOnglet : 'personnes';
}

function equipeChoisirOnglet(onglet) {
  state.equipeOnglet = equipeOngletsPermis().includes(onglet) ? onglet : 'personnes';
  state.equipeRenommage = null;
  save();
  renderStaffUtilityPage();
}

function equipeChoisirPersonne(memberId) {
  const access = ensureStaffAccessControl();
  if (!access.members.some(member => member.id === memberId)) return;
  access.selectedMemberId = memberId;
  state.equipeRenommage = null;
  save();
  renderStaffUtilityPage();
  // Au téléphone, la fiche est sous la liste : on y descend.
  if (window.matchMedia && window.matchMedia('(max-width: 900px)').matches) {
    document.querySelector('.eq-fiche')?.scrollIntoView({ block: 'start', behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
  }
}

function equipeChoisirRole(roleId) {
  const access = ensureStaffAccessControl();
  const role = access.roles.find(item => item.id === roleId);
  if (!role || isPlatformStaffRole(role)) return;
  access.selectedRoleId = roleId;
  state.equipeOnglet = 'roles';
  state.equipeRenommage = null;
  save();
  renderStaffUtilityPage();
}

// ---- Les gestes sur une personne -------------------------------------------

function equipeRenommer(type, id) {
  state.equipeRenommage = { type, id };
  renderStaffUtilityPage();
  const champ = document.getElementById('equipeRenommage');
  if (champ) { champ.focus(); champ.select(); }
}

async function equipeValiderRenommage() {
  const enCours = state.equipeRenommage;
  const champ = document.getElementById('equipeRenommage');
  if (!enCours || !champ) return;
  const nom = String(champ.value || '').trim();
  state.equipeRenommage = null;
  if (!nom) { renderStaffUtilityPage(); return; }
  // (rien de plateforme ne se renomme d ici, ni role ni personne)
  const access = ensureStaffAccessControl();
  const plateforme = enCours.type === 'role'
    ? isPlatformStaffRole((access.roles || []).find(role => role.id === enCours.id))
    : isPlatformStaffMember(access, (access.members || []).find(member => member.id === enCours.id));
  if (plateforme) { renderStaffUtilityPage(); return; }
  if (enCours.type === 'role') {
    await runStaffAuthAction('renameRole', { roleId: enCours.id, name: nom }, 'Rôle renommé.');
  } else {
    await runStaffAuthAction('renameMember', { memberId: enCours.id, name: nom }, 'Nom changé.');
  }
}

function equipeAnnulerRenommage() {
  state.equipeRenommage = null;
  renderStaffUtilityPage();
}

async function equipeBloquer(memberId, bloque) {
  const access = ensureStaffAccessControl();
  const member = access.members.find(item => item.id === memberId);
  // (l acces plateforme ne se gere jamais d ici, meme par un appel direct)
  if (!member || isPlatformStaffMember(access, member) || equipeEstSoi(member)) return;
  const autres = equipeCentresDe(member).length > 1 ? ' dans tous ses centres' : '';
  if (bloque && !window.confirm(`Bloquer ${member.name}${autres} ? Son code n’ouvrira plus rien et sa console se ferme tout de suite.`)) return;
  await runStaffAuthAction('setMemberBlocked', { memberId, bloque: Boolean(bloque) }, bloque ? `${member.name} est bloqué.` : `${member.name} peut de nouveau entrer.`);
}

async function equipeSupprimer(memberId) {
  const access = ensureStaffAccessControl();
  const member = access.members.find(item => item.id === memberId);
  if (!member || isPlatformStaffMember(access, member) || equipeEstSoi(member)) return;
  const centres = equipeCentresDe(member).length;
  if (!window.confirm(`Supprimer ${member.name}${centres > 1 ? ` de ses ${centres} centres` : ''} ? Son code n’ouvrira plus rien. Cela ne s’annule pas.`)) return;
  const reponse = await runStaffAuthAction('supprimerPersonne', { memberId }, `${member.name} est supprimé.`);
  if (reponse && state.staffAccessControl) state.staffAccessControl.selectedMemberId = '';
}

async function equipeNouveauCode(memberId) {
  const access = ensureStaffAccessControl();
  const member = access.members.find(item => item.id === memberId);
  if (!member || isPlatformStaffMember(access, member)) return;
  if (!window.confirm(`Donner un nouveau code à ${member.name} ? L’ancien n’ouvrira plus rien, dans tous ses centres.`)) return;
  await runStaffAuthAction('regenerateMemberCode', { memberId }, `Nouveau code pour ${member.name}.`);
}

// Donner, changer ou retirer l'accès d'une personne à un centre de l'entreprise.
async function equipeRoleAuCentre(memberId, centreId, roleId) {
  const access = ensureStaffAccessControl();
  const member = access.members.find(item => item.id === memberId);
  if (!member || isPlatformStaffMember(access, member)) return;
  // (et jamais un role plateforme donne depuis cette page)
  if (roleId && isPlatformStaffRole((access.roles || []).find(role => role.id === roleId))) return;
  const nomCentre = equipeNomDuCentre(access, centreId);
  if (!roleId) {
    if (!window.confirm(`Retirer à ${member.name} l’accès à ${nomCentre} ?`)) { renderStaffUtilityPage(); return; }
    await runStaffAuthAction('setMemberCenter', { memberId, cibleCenterId: centreId, roleId: '' }, `${member.name} n’entre plus à ${nomCentre}.`);
    return;
  }
  if (centreId === access.centerId) {
    await updateStaffMemberRole(memberId, roleId);
    return;
  }
  await runStaffAuthAction('setMemberCenter', { memberId, cibleCenterId: centreId, roleId }, `${member.name} : accès à ${nomCentre} enregistré.`);
}

// ---- Le rendu ---------------------------------------------------------------

function equipeChampRenommage(type, id, valeur, etiquette) {
  return `<span class="eq-renommage">
    <label class="visually-hidden" for="equipeRenommage">${escapeHtml(etiquette)}</label>
    <input id="equipeRenommage" type="text" maxlength="${type === 'role' ? 60 : 80}" value="${escapeHtml(valeur)}" autocomplete="off" data-eq-type="${escapeHtml(type)}" data-eq-id="${escapeHtml(id)}">
    <button type="button" class="btn btn-primary btn-sm" data-eq="renommage-ok">Enregistrer</button>
    <button type="button" class="btn btn-ghost btn-sm" data-eq="renommage-annuler">Annuler</button>
  </span>`;
}

function equipeBadgeEtat(status) {
  const [mot, classe] = EQUIPE_ETATS[status] || ['Inconnu', 'badge-neutral'];
  return `<span class="badge ${classe}">${escapeHtml(mot)}</span>`;
}

function equipeLigne(access, member, choisi) {
  const role = equipeRoleDe(access, member);
  const centres = equipeCentresDe(member).map(centre => equipeNomDuCentre(access, centre.centerId));
  const vuLe = equipeVuDeLaPersonne(member);
  const etat = equipeEtatDeLaPersonne(member);
  const vu = vuLe ? `Venu ${equipeQuand(vuLe)}` : (etat === 'blocked' ? '' : 'Pas encore venu');
  return `<button type="button" class="eq-ligne${choisi ? ' is-choisie' : ''}${member.status === 'blocked' ? ' is-bloquee' : ''}" data-eq="personne" data-id="${escapeHtml(member.id)}" ${choisi ? 'aria-current="true"' : ''}>
    <span class="eq-avatar" aria-hidden="true">${escapeHtml(getStaffClientInitials(member.name))}</span>
    <span class="eq-ligne-qui"><strong>${escapeHtml(member.name)}</strong><small>${escapeHtml(member.partage ? 'Code partagé du rôle' : (member.contact || 'Sans contact'))}</small></span>
    <span class="eq-ligne-role">${escapeHtml(role.name)}</span>
    <span class="eq-ligne-centres">${escapeHtml(centres.join(' · '))}</span>
    <span class="eq-ligne-etat">${equipeBadgeEtat(etat)}</span>
    <span class="eq-ligne-vu">${escapeHtml(vu)}</span>
  </button>`;
}

function equipeBlocCentres(access, member) {
  const soi = equipeEstSoi(member);
  const centresPersonne = equipeCentresDe(member);
  const donneDirection = equipePeutDonnerDirection();
  // Le centre qu'on regarde d'abord, puis ceux où la personne entre, puis les autres.
  const rang = centre => (centre.id === access.centerId ? 0 : (centresPersonne.some(item => item.centerId === centre.id) ? 1 : 2));
  const lignes = (access.entreprise && access.entreprise.length ? access.entreprise : [{ id: access.centerId, name: access.centerId, gere: true, roles: access.roles }])
    .slice()
    .sort((a, b) => rang(a) - rang(b) || String(a.id).localeCompare(String(b.id)))
    .map(centre => {
      const ici = centresPersonne.find(item => item.centerId === centre.id);
      const roles = (centre.roles || []).filter(role => !isPlatformStaffRole(role) && (!role.locked || donneDirection));
      const nom = equipeNomDuCentre(access, centre.id);
      const peutChanger = centre.gere && !soi && !member.partage;
      if (ici) {
        const nomRole = ici.roleName || ((centre.roles || []).find(role => role.id === ici.roleId) || {}).name || ici.roleId;
        const garderRole = roles.some(role => role.id === ici.roleId) ? '' : `<option value="${escapeHtml(ici.roleId)}" selected>${escapeHtml(nomRole)}</option>`;
        return `<li class="eq-centre">
          <span class="eq-centre-nom">${escapeHtml(nom)}</span>
          ${peutChanger
            ? `<label class="visually-hidden" for="eqRole-${escapeHtml(centre.id)}">Rôle de ${escapeHtml(member.name)} à ${escapeHtml(nom)}</label>
              <select id="eqRole-${escapeHtml(centre.id)}" data-eq="role-au-centre" data-id="${escapeHtml(member.id)}" data-centre="${escapeHtml(centre.id)}">
                ${garderRole}${roles.map(role => `<option value="${escapeHtml(role.id)}" ${role.id === ici.roleId ? 'selected' : ''}>${escapeHtml(role.name)}</option>`).join('')}
              </select>
              ${centresPersonne.length > 1 ? `<button type="button" class="btn btn-ghost btn-sm" data-eq="retirer-centre" data-id="${escapeHtml(member.id)}" data-centre="${escapeHtml(centre.id)}">Retirer</button>` : ''}`
            : `<span class="eq-centre-role">${escapeHtml(nomRole)}</span>`}
        </li>`;
      }
      if (!peutChanger || !roles.length) return '';
      return `<li class="eq-centre is-sans">
        <span class="eq-centre-nom">${escapeHtml(nom)}</span>
        <label class="visually-hidden" for="eqRole-${escapeHtml(centre.id)}">Donner à ${escapeHtml(member.name)} un accès à ${escapeHtml(nom)}</label>
        <select id="eqRole-${escapeHtml(centre.id)}" data-eq="role-au-centre" data-id="${escapeHtml(member.id)}" data-centre="${escapeHtml(centre.id)}">
          <option value="" selected>Pas d’accès</option>
          ${roles.map(role => `<option value="${escapeHtml(role.id)}">Entre comme ${escapeHtml(role.name)}</option>`).join('')}
        </select>
      </li>`;
    }).join('');
  return `<section class="eq-bloc">
    <h4>Ses centres</h4>
    <ul class="eq-centres">${lignes}</ul>
    <p class="eq-aide">Dans chaque centre, la personne a le rôle choisi ici. Elle passe d’un centre à l’autre par le menu en haut à gauche.</p>
  </section>`;
}

function equipeBlocCode(member) {
  const fin = String(member.code || member.accessCodeHint || '').replace(/^[^A-Z0-9]+/i, '').replace(/^•+-?/, '');
  const peutCodes = canUseStaffPermission('security.codes');
  if (member.partage) {
    return `<section class="eq-bloc">
      <h4>Son code</h4>
      <p class="eq-phrase">C’est le code partagé du rôle : il se change dans l’onglet Rôles.</p>
    </section>`;
  }
  return `<section class="eq-bloc">
    <h4>Son code</h4>
    <p class="eq-phrase">Pour entrer, la personne tape son code. ${fin ? `Il finit par <strong class="eq-code">${escapeHtml(fin)}</strong>.` : ''}</p>
    ${peutCodes ? `<div class="eq-actions">
      <button type="button" class="btn btn-secondary btn-sm" data-eq="copier-code" data-id="${escapeHtml(member.id)}">Copier le code</button>
      <button type="button" class="btn btn-secondary btn-sm" data-eq="nouveau-code" data-id="${escapeHtml(member.id)}">Nouveau code</button>
    </div>
    <p class="eq-aide">Copier le code le met dans le presse-papiers, pour le lui envoyer. Un nouveau code remplace l’ancien tout de suite.</p>` : ''}
  </section>`;
}

function equipeBlocVoit(access, member) {
  const role = equipeRoleDe(access, member);
  const menu = equipeMenuDuRole(role);
  const fermes = equipeEcransFermes(role);
  const ici = equipeNomDuCentre(access, access.centerId);
  return `<section class="eq-bloc">
    <h4>Ce qu’il voit à ${escapeHtml(ici)}</h4>
    <p class="eq-phrase">Le rôle ${escapeHtml(role.name)} lui ouvre : ${escapeHtml(menu.flatMap(section => section.items.map(item => item.label)).join(', ') || 'aucun écran')}.</p>
    ${fermes.length ? `<p class="eq-phrase eq-ferme">Il ne voit pas : ${escapeHtml(fermes.join(', '))}.</p>` : '<p class="eq-phrase">Il voit tous les écrans.</p>'}
    ${isPlatformStaffRole(role) ? '' : `<button type="button" class="btn btn-ghost btn-sm" data-eq="voir-role" data-id="${escapeHtml(role.id)}">Voir le détail du rôle ${escapeHtml(role.name)}</button>`}
  </section>`;
}

function equipeFiche(access, member) {
  if (!member) {
    return `<aside class="eq-fiche eq-vide"><p>Choisissez une personne pour voir sa fiche.</p></aside>`;
  }
  const soi = equipeEstSoi(member);
  const renommage = state.equipeRenommage && state.equipeRenommage.type === 'membre' && state.equipeRenommage.id === member.id;
  const role = equipeRoleDe(access, member);
  const centres = equipeCentresDe(member).map(centre => equipeNomDuCentre(access, centre.centerId));
  const vuLe = equipeVuDeLaPersonne(member);
  const etat = member.status === 'blocked'
    ? 'Bloqué : son code n’ouvre plus rien.'
    : (vuLe ? `Actif : venu ${equipeQuand(vuLe)}.` : 'Pas encore venu : il n’a jamais tapé son code.');
  return `<aside class="eq-fiche" aria-label="Fiche de ${escapeHtml(member.name)}">
    <div class="eq-fiche-tete">
      <span class="eq-avatar is-grand" aria-hidden="true">${escapeHtml(getStaffClientInitials(member.name))}</span>
      <div class="eq-fiche-nom">
        ${renommage ? equipeChampRenommage('membre', member.id, member.name, `Nouveau nom de ${member.name}`) : `<h3>${escapeHtml(member.name)}${soi ? ' <small>(vous)</small>' : ''}</h3>`}
        <p>${escapeHtml(role.name)} · ${escapeHtml(centres.join(' et '))}</p>
      </div>
      ${renommage ? '' : `<button type="button" class="btn btn-ghost btn-sm" data-eq="renommer-personne" data-id="${escapeHtml(member.id)}">Renommer</button>`}
    </div>
    <p class="eq-etat">${equipeBadgeEtat(equipeEtatDeLaPersonne(member))} <span>${escapeHtml(etat)}</span></p>
    ${member.contact && !member.partage ? `<p class="eq-contact">${escapeHtml(member.contact)}</p>` : ''}
    ${equipeBlocCentres(access, member)}
    ${equipeBlocCode(member)}
    ${equipeBlocVoit(access, member)}
    ${soi ? '' : `<div class="eq-fiche-pied">
      ${member.status === 'blocked'
        ? `<button type="button" class="btn btn-secondary btn-sm" data-eq="debloquer" data-id="${escapeHtml(member.id)}">Débloquer</button>`
        : `<button type="button" class="btn btn-secondary btn-sm" data-eq="bloquer" data-id="${escapeHtml(member.id)}">Bloquer</button>`}
      <button type="button" class="btn btn-ghost btn-sm staff-danger-btn" data-eq="supprimer" data-id="${escapeHtml(member.id)}">Supprimer</button>
    </div>`}
  </aside>`;
}

function equipeOngletPersonnes(access) {
  const personnes = equipePersonnes(access);
  const nommees = personnes.filter(member => !member.partage);
  const partagees = personnes.filter(member => member.partage);
  const choisi = equipeMembreChoisi(access);
  const ici = equipeNomDuCentre(access, access.centerId);
  const actives = nommees.filter(member => member.status !== 'blocked').length;
  return `<div class="eq-personnes">
    <section class="eq-liste" aria-label="Les personnes">
      <p class="eq-intro">${actives > 1 ? `${actives} personnes entrent` : (actives === 1 ? 'Une personne entre' : 'Personne n’entre encore')} dans la console de ${escapeHtml(ici)}. Chacune a son code : elle le tape une fois, et la console s’ouvre sur ce que son rôle lui permet de voir.</p>
      <div class="eq-entete" aria-hidden="true"><span></span><span>Personne</span><span>Rôle ici</span><span>Centres</span><span>État</span><span>Dernière visite</span></div>
      ${nommees.length ? nommees.map(member => equipeLigne(access, member, choisi && choisi.id === member.id)).join('') : '<p class="eq-vide">Personne pour l’instant. « Ajouter une personne » crée son code.</p>'}
      ${partagees.length ? `<h4 class="eq-sous-titre">Codes partagés</h4>
        <p class="eq-aide">Ces entrées viennent du code d’un rôle, tapé sans nom (une tablette commune, par exemple). Ce code se change dans l’onglet Rôles.</p>
        ${partagees.map(member => equipeLigne(access, member, choisi && choisi.id === member.id)).join('')}` : ''}
    </section>
    ${equipeFiche(access, choisi)}
  </div>`;
}

function equipeInterrupteur(roleId, permission, actif, mot, phrase, enfant) {
  const id = `eqDroit-${permission.replace(/[^a-z0-9]/gi, '-')}`;
  return `<div class="eq-droit${enfant ? ' is-enfant' : ''}">
    <input type="checkbox" role="switch" id="${id}" class="eq-switch" data-eq="droit" data-role="${escapeHtml(roleId)}" data-permission="${escapeHtml(permission)}" ${actif ? 'checked' : ''}>
    <label for="${id}"><strong>${escapeHtml(mot)}</strong><span>${escapeHtml(phrase)}</span></label>
  </div>`;
}

function equipeNiveaux(role, droits) {
  const agit = droits.has('reservations.create') || droits.has('reservations.edit');
  if (!agit) return '';
  const permissions = role.permissions || [];
  return `<div class="eq-niveaux">
    <p class="eq-niveaux-titre">Sur une réservation, jusqu’où</p>
    ${DROITS_NIVEAUX.map(({ cle, libelle, options }) => {
      const valeur = niveauDesPermissions(permissions, cle);
      return `<div class="eq-niveau" role="radiogroup" aria-labelledby="eqNiveau-${cle}">
        <span id="eqNiveau-${cle}" class="eq-niveau-nom">${escapeHtml(libelle)}</span>
        <span class="eq-niveau-choix">${options.map(([option, mot]) => `<label class="eq-niveau-option">
          <input type="radio" class="visually-hidden" name="eqNiveau-${cle}" data-eq="niveau" data-role="${escapeHtml(role.id)}" data-cle="${escapeHtml(cle)}" value="${escapeHtml(option)}" data-niveau-choix="${cle}:${option}" ${valeur === option ? 'checked' : ''}>
          <span>${escapeHtml(mot)}</span>
        </label>`).join('')}</span>
      </div>`;
    }).join('')}
  </div>`;
}

function equipeCarteDuRole(role) {
  const droits = equipeDroitsDuRole(role);
  if (role.locked) {
    return `<p class="eq-note">${escapeHtml(role.name)} voit tous les écrans et peut tout faire dans ce centre. Ses droits ne se règlent pas : c’est le rôle de ceux qui dirigent.</p>`;
  }
  return CARTE_DES_DROITS.map(groupe => `<section class="eq-groupe">
    <h4>${escapeHtml(groupe.section)}</h4>
    ${groupe.ecrans.map(ecran => {
      const ouvert = equipeEcranOuvert(ecran, droits, false);
      const gestes = (ecran.droits || []);
      const tete = ecran.ouvre
        ? equipeInterrupteur(role.id, ecran.ouvre[0], droits.has(ecran.ouvre[0]), ecran.nom, ecran.phrase, false)
        : `<div class="eq-droit is-titre"><span class="eq-ecran-etat ${ouvert ? 'is-ouvert' : ''}" aria-hidden="true"></span><p><strong>${escapeHtml(ecran.nom)}</strong><span>${escapeHtml(ecran.phrase)}</span></p></div>`;
      const ouvrePar = ecran.ouvrePar
        ? `<p class="eq-ouvre-par">${ouvert ? 'Ouvert' : 'Fermé'} : s’ouvre avec ${ecran.ouvrePar.map(permission => `« ${escapeHtml(equipeMotDuDroit(permission))} »`).join(' ou ')}.</p>`
        : '';
      // Un écran fermé ne montre pas ses gestes : ils n'agiraient pas.
      const montrerGestes = ecran.ouvre ? droits.has(ecran.ouvre[0]) : true;
      return `<article class="eq-ecran${ouvert ? ' is-ouvert' : ''}">
        ${tete}
        ${ouvrePar}
        ${montrerGestes && gestes.length ? `<div class="eq-gestes">${gestes.map(([permission, mot, phrase]) => equipeInterrupteur(role.id, permission, droits.has(permission), mot, phrase, true)).join('')}</div>` : ''}
        ${montrerGestes && ecran.niveaux ? equipeNiveaux(role, droits) : ''}
      </article>`;
    }).join('')}
  </section>`).join('');
}

function equipeMotDuDroit(permission) {
  for (const groupe of CARTE_DES_DROITS) {
    for (const ecran of groupe.ecrans) {
      if (ecran.ouvre && ecran.ouvre[0] === permission) return ecran.ouvre[1];
      const trouve = (ecran.droits || []).find(([p]) => p === permission);
      if (trouve) return trouve[1];
    }
  }
  return permission;
}

function equipeApercu(access, role) {
  const menu = equipeMenuDuRole(role);
  const fermes = equipeEcransFermes(role);
  const personnes = equipePersonnes(access).filter(member => member.roleId === role.id && !member.partage);
  const peutCodes = canUseStaffPermission('security.codes');
  const fin = String(role.accessCodeHint || role.accessCode || '').replace(/^•+-?/, '');
  return `<aside class="eq-apercu" aria-label="Ce que voit le rôle ${escapeHtml(role.name)}">
    <section class="eq-bloc">
      <h4>Son menu</h4>
      <p class="eq-aide">Exactement ce qu’une personne ${escapeHtml(role.name)} voit à gauche de sa console.</p>
      <nav class="eq-menu" aria-label="Menu du rôle ${escapeHtml(role.name)}">
        ${menu.length ? menu.map(section => `<p class="eq-menu-section">${escapeHtml(section.titre)}</p>
          <ul>${section.items.map(item => `<li>${escapeHtml(item.label)}${item.enfants.length ? `<span>${escapeHtml(item.enfants.join(' · '))}</span>` : ''}</li>`).join('')}</ul>`).join('') : '<p class="eq-vide">Aucun écran : ce rôle n’ouvre rien.</p>'}
      </nav>
      ${fermes.length ? `<p class="eq-phrase eq-ferme">Ne voit pas : ${escapeHtml(fermes.join(', '))}.</p>` : ''}
    </section>
    <section class="eq-bloc">
      <h4>Les personnes</h4>
      ${personnes.length ? `<ul class="eq-noms">${personnes.map(member => `<li><button type="button" class="eq-lien" data-eq="ouvrir-personne" data-id="${escapeHtml(member.id)}">${escapeHtml(member.name)}</button></li>`).join('')}</ul>` : '<p class="eq-phrase">Personne n’a ce rôle ici.</p>'}
    </section>
    <section class="eq-bloc">
      <h4>Le code partagé du rôle</h4>
      <p class="eq-phrase">Quiconque tape ce code entre comme ${escapeHtml(role.name)}, sans son nom. Utile pour une tablette commune.${fin ? ` Il finit par <strong class="eq-code">${escapeHtml(fin)}</strong>.` : ''}</p>
      ${peutCodes ? `<div class="eq-actions">
        <button type="button" class="btn btn-secondary btn-sm" data-eq="copier-code-role" data-role="${escapeHtml(role.id)}">Copier le code</button>
        <button type="button" class="btn btn-secondary btn-sm" data-eq="nouveau-code-role" data-role="${escapeHtml(role.id)}">Nouveau code</button>
      </div>` : ''}
    </section>
  </aside>`;
}

function equipeOngletRoles(access) {
  const roles = getVisibleStaffAccessRoles(access);
  const role = getStaffAccessRole(access.selectedRoleId);
  const personnes = equipePersonnes(access);
  const renommage = state.equipeRenommage && state.equipeRenommage.type === 'role' && state.equipeRenommage.id === role.id;
  const peutRenommer = !role.locked || equipeEstProprietaire();
  const membres = personnes.filter(member => member.roleId === role.id).length;
  const modeles = STAFF_ROLE_PRESETS.filter(preset => preset.id !== 'direction');
  return `<div class="eq-roles">
    <nav class="eq-rail" aria-label="Les rôles">
      ${roles.map(item => {
        const nb = personnes.filter(member => member.roleId === item.id && !member.partage).length;
        return `<button type="button" class="eq-rail-role${item.id === role.id ? ' is-choisi' : ''}" data-eq="role" data-id="${escapeHtml(item.id)}" ${item.id === role.id ? 'aria-current="true"' : ''}>
          <strong>${escapeHtml(item.name)}</strong>
          <small>${nb ? `${nb} personne${nb > 1 ? 's' : ''}` : 'Personne'}</small>
        </button>`;
      }).join('')}
    </nav>
    <section class="eq-role" aria-label="Le rôle ${escapeHtml(role.name)}">
      <div class="eq-role-tete">
        <div>
          ${renommage ? equipeChampRenommage('role', role.id, role.name, `Nouveau nom du rôle ${role.name}`) : `<h3>${escapeHtml(role.name)}</h3>`}
          <p>${escapeHtml(role.description || role.summary || 'Rôle créé par le centre.')}</p>
        </div>
        <div class="eq-actions">
          ${peutRenommer && !renommage ? `<button type="button" class="btn btn-ghost btn-sm" data-eq="renommer-role" data-id="${escapeHtml(role.id)}">Renommer</button>` : ''}
          ${!role.locked && !membres ? `<button type="button" class="btn btn-ghost btn-sm staff-danger-btn" data-eq="supprimer-role" data-id="${escapeHtml(role.id)}">Supprimer le rôle</button>` : ''}
          ${role.locked ? '' : `<label class="visually-hidden" for="eqModele">Repartir des droits d’un modèle</label>
            <select id="eqModele" data-eq="modele" data-role="${escapeHtml(role.id)}">
              <option value="" selected>Repartir d’un modèle…</option>
              ${modeles.map(preset => `<option value="${escapeHtml(preset.id)}">${escapeHtml(preset.name)}</option>`).join('')}
            </select>`}
        </div>
      </div>
      ${role.locked ? '' : '<p class="eq-aide">Chaque interrupteur ouvre ou ferme un écran, ou un geste sur cet écran. Fermer un écran le retire du menu de la personne, avec tout ce qu’il contient.</p>'}
      ${equipeCarteDuRole(role)}
    </section>
    ${equipeApercu(access, role)}
  </div>`;
}

function equipeOngletJournal(access) {
  const nomDe = id => ((access.members || []).find(member => member.id === id) || {}).name || '';
  const evenements = (access.events || []).filter(event => event && event.label);
  return `<section class="eq-journal" aria-label="Journal">
    <p class="eq-intro">Les vingt derniers changements de l’équipe dans ce centre : codes, rôles, accès, connexions.</p>
    ${evenements.length ? `<ol class="eq-journal-liste">${evenements.map(event => {
      const qui = nomDe(event.actorMemberId);
      return `<li><time>${escapeHtml(event.at ? formatOpsTimestamp(event.at) : '')}</time><span>${escapeHtml(event.label)}${qui && !String(event.label).startsWith(qui) ? ` <small>par ${escapeHtml(qui)}</small>` : ''}</span></li>`;
    }).join('')}</ol>` : '<p class="eq-vide">Rien pour l’instant.</p>'}
  </section>`;
}

function renderStaffUtilityUsers() {
  const access = ensureStaffAccessControl();
  const onglet = equipeOnglet();
  const personnes = equipePersonnes(access).filter(member => !member.partage);
  const roles = getVisibleStaffAccessRoles(access);
  const corps = onglet === 'roles'
    ? equipeOngletRoles(access)
    : (onglet === 'journal' ? equipeOngletJournal(access) : equipeOngletPersonnes(access));
  equipeBrancher();
  return `<div class="eq" data-equipe-page>
    <div class="eq-onglets" role="tablist" aria-label="Équipe & accès">
      <button type="button" role="tab" id="eqOnglet-personnes" aria-selected="${onglet === 'personnes'}" data-eq="onglet" data-valeur="personnes">Personnes <em>${personnes.length}</em></button>
      <button type="button" role="tab" id="eqOnglet-roles" aria-selected="${onglet === 'roles'}" data-eq="onglet" data-valeur="roles">Rôles <em>${roles.length}</em></button>
      ${equipeOngletsPermis().includes('journal') ? `<button type="button" role="tab" id="eqOnglet-journal" aria-selected="${onglet === 'journal'}" data-eq="onglet" data-valeur="journal">Journal</button>` : ''}
    </div>
    <div role="tabpanel" aria-labelledby="eqOnglet-${onglet}">${corps}</div>
  </div>`;
}

// UN SEUL ECOUTEUR, pose une fois sur la page qui porte l'écran (elle survit
// aux rendus) : les boutons portent leur geste dans data-eq.
function equipeBrancher() {
  const racine = document.getElementById('staffUtilityPage');
  if (!racine || racine.__equipeBranche) return;
  racine.__equipeBranche = true;
  racine.addEventListener('click', event => {
    const cible = event.target.closest('[data-eq]');
    if (!cible || !racine.contains(cible) || !cible.closest('[data-equipe-page]')) return;
    const geste = cible.dataset.eq;
    const id = cible.dataset.id || '';
    if (geste === 'onglet') equipeChoisirOnglet(cible.dataset.valeur);
    else if (geste === 'personne') equipeChoisirPersonne(id);
    else if (geste === 'ouvrir-personne') { state.equipeOnglet = 'personnes'; equipeChoisirPersonne(id); }
    else if (geste === 'role' || geste === 'voir-role') equipeChoisirRole(id);
    else if (geste === 'renommer-personne') equipeRenommer('membre', id);
    else if (geste === 'renommer-role') equipeRenommer('role', id);
    else if (geste === 'renommage-ok') equipeValiderRenommage();
    else if (geste === 'renommage-annuler') equipeAnnulerRenommage();
    else if (geste === 'copier-code') copyStaffMemberCode(id);
    else if (geste === 'nouveau-code') equipeNouveauCode(id);
    else if (geste === 'bloquer') equipeBloquer(id, true);
    else if (geste === 'debloquer') equipeBloquer(id, false);
    else if (geste === 'supprimer') equipeSupprimer(id);
    else if (geste === 'retirer-centre') equipeRoleAuCentre(id, cible.dataset.centre, '');
    else if (geste === 'copier-code-role') copyStaffRoleCode(cible.dataset.role);
    else if (geste === 'nouveau-code-role') {
      const role = getStaffAccessRole(cible.dataset.role);
      if (role && window.confirm(`Donner un nouveau code partagé au rôle ${role.name} ? L’ancien n’ouvrira plus rien.`)) regenerateStaffAccessCode(role.id);
    }
    else if (geste === 'supprimer-role') deleteStaffRole(id);
  });
  racine.addEventListener('change', event => {
    const cible = event.target.closest('[data-eq]');
    if (!cible || !cible.closest('[data-equipe-page]')) return;
    const geste = cible.dataset.eq;
    if (geste === 'droit') toggleStaffRolePermission(cible.dataset.role, cible.dataset.permission, cible.checked);
    else if (geste === 'niveau') choisirNiveauRole(cible.dataset.role, cible.dataset.cle, cible.value);
    else if (geste === 'role-au-centre') equipeRoleAuCentre(cible.dataset.id, cible.dataset.centre, cible.value);
    else if (geste === 'modele' && cible.value) {
      const modele = STAFF_ROLE_PRESETS.find(preset => preset.id === cible.value);
      const role = getStaffAccessRole(cible.dataset.role);
      if (modele && role && window.confirm(`Donner au rôle ${role.name} les droits du modèle ${modele.name} ? Ses droits actuels sont remplacés.`)) setStaffRolePreset(role.id, modele.id);
      else renderStaffUtilityPage();
    }
  });
  racine.addEventListener('keydown', event => {
    if (event.target && event.target.id === 'equipeRenommage') {
      if (event.key === 'Enter') { event.preventDefault(); equipeValiderRenommage(); }
      if (event.key === 'Escape') { event.preventDefault(); equipeAnnulerRenommage(); }
    }
  });
}

// ===========================================================================
// Blocages de disponibilite (page Etablissement, permission settings.manage).
// Le centre est celui de la SESSION : le serveur le force, on ne l'envoie
// jamais dans le corps. Lecture via listAvailabilityBlocks, ecritures via
// saveAvailabilityBlock / deleteAvailabilityBlock (meme apiRequest que la
// config centre). Le planning consomme le meme cache pour marquer, en lecture
// seule, les ressources bloquees le jour affiche.
// ===========================================================================
let availabilityBlocksCache = { loaded: false, loading: false, error: '', blocks: [] };
const AVAILABILITY_DAY_NAMES = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];

// LE CENTRE DE LA SESSION, et lui seul : le repli sur le premier centre de la
// liste donnait a un centre absent du cache les capacites d un AUTRE centre.
// Absent, on ne sait pas, et les lecteurs ci-dessous passent a la source
// suivante.
function getAvailabilitySessionCenter() {
  const centers = staffCenterConfigCache.centers || [];
  const id = getCurrentStaffCenterId();
  return centers.find(center => center.id === id) || null;
}

// LES CAPACITES DU CENTRE ONT UNE SOURCE, PAS TRENTE-TROIS. La console lisait
// les constantes (8 pistes, 30 armes, 1 lancement) a l allocation des pistes,
// dans les selecteurs, la capacite de l accueil, le tableau laser, pendant que
// la grille lisait la configuration. Ordre : la configuration staff du centre
// (la plus fraiche apres une modification dans Etablissement), sinon celle que
// le serveur sert au tunnel pour ce meme centre (public-booking-meta, lisible
// par TOUS les roles : un role sans reglages ni direction n a pas la
// premiere, et retombait sur 8 / 30 / 1 quel que soit le centre), sinon la
// constante, dernier recours d un centre qui n a rien declare.
function capaciteDeclaree(valeur) {
  const nombre = Number(valeur);
  return Number.isFinite(nombre) && nombre > 0 ? Math.min(Math.trunc(nombre), 200) : 0;
}

// La configuration du tunnel ne vaut que pour SON centre. Apres une bascule
// de centre, celle du centre precedent reste en memoire jusqu a la reponse
// suivante : ses nombres seraient ceux d un autre client.
function capaciteDuTunnel(lire) {
  const config = typeof getCenterScheduleConfig === 'function' ? getCenterScheduleConfig() : null;
  const attendu = state.view === 'client' ? getTunnelCenterId() : getCurrentStaffCenterId();
  if (!config || !config.id || config.id !== attendu || typeof lire !== 'function') return 0;
  return capaciteDeclaree(lire());
}

function getAvailabilityLaneCount() {
  return capaciteDeclaree(getAvailabilitySessionCenter()?.resources?.bowling?.laneCount)
    || capaciteDuTunnel(typeof getTotalLanes === 'function' ? getTotalLanes : null)
    || TOTAL_LANES;
}

// Postes de l arene (armes) du centre affiche.
function getAvailabilityLaserCapacity() {
  return capaciteDeclaree(getAvailabilitySessionCenter()?.resources?.laser?.weaponCount)
    || capaciteDuTunnel(typeof getLaserArenaCapacity === 'function' ? getLaserArenaCapacity : null)
    || LASER_GAME_MAX_PLAYERS;
}

// Lancements laser qui tournent en meme temps (Gembloux : 6, Libramont : 1).
function getAvailabilityLaserParallelLaunches() {
  return capaciteDeclaree(getAvailabilitySessionCenter()?.resources?.laser?.parallelLaunches)
    || capaciteDuTunnel(typeof getLaserParallelLaunches === 'function' ? getLaserParallelLaunches : null)
    || LASER_GAME_PARALLEL_LAUNCHES;
}

// Les paires de pistes voisines d un centre a N pistes (1-2, 3-4...), la
// regle du serveur (pairsForLaneCount) : la constante PAIRS n en connait que
// quatre, celles d un centre a 8 pistes.
function getAvailabilityLanePairs(laneCount = getAvailabilityLaneCount()) {
  const pairs = [];
  for (let lane = 1; lane + 1 <= laneCount; lane += 2) pairs.push([lane, lane + 1]);
  return pairs;
}

// Pistes en maintenance PARMI celles du centre : un drapeau laisse sur une
// piste retiree (7 ou 8 d un centre passe a 6) ne retire rien a la capacite.
function getAvailabilityLanesInMaintenance(laneCount = getAvailabilityLaneCount()) {
  return Object.entries(state.laneStatuses || {})
    .filter(([lane, status]) => status === 'maintenance' && Number(lane) >= 1 && Number(lane) <= laneCount)
    .length;
}

// Declenche (au plus une fois) le chargement de la config centre pour que le
// planning reflete la vraie capacite. Idempotent et sans risque : loadStaffCenterConfig
// s'auto-garde (deja charge / en cours / permission) et ne fait AUCUNE requete pour
// un staff sans droit de configuration (repli silencieux sur les constantes). Le
// prochain re-render du polling reprend la config une fois chargee.
function ensureStaffCenterConfigForPlanning() {
  if (!staffCenterConfigCache.loaded && !staffCenterConfigCache.loading) {
    loadStaffCenterConfig(false);
  }
}

function getAvailabilityActivities() {
  const center = getAvailabilitySessionCenter();
  const all = staffCenterConfigCache.activities || [];
  const enabled = all.filter(activity => center?.activityAvailability?.[activity.id]);
  return enabled.length ? enabled : all;
}

function availabilityActivityLabel(id) {
  const found = (staffCenterConfigCache.activities || []).find(activity => activity.id === id);
  return found ? found.label : String(id || '');
}

function availabilityFormulaLabel(id) {
  const found = resolveDisplayFormule(id);
  return found ? found.name : String(id || '');
}

// La liste serveur renvoie startMin/endMin (minutes, ou null pour jour entier).
// On tolere aussi startTime/endTime au cas ou la forme evoluerait.
function availabilityBlockStartMin(block) {
  if (typeof block.startMin === 'number') return block.startMin;
  if (block.startTime) { const [h, m] = String(block.startTime).split(':').map(Number); return (h * 60) + (m || 0); }
  return null;
}

function availabilityBlockEndMin(block) {
  if (typeof block.endMin === 'number') return block.endMin;
  if (block.endTime) { const [h, m] = String(block.endTime).split(':').map(Number); return (h * 60) + (m || 0); }
  return null;
}

function availabilityMinutesToHHMM(min) {
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

function availabilityScopeText(block) {
  if (block.scopeType === 'center') return 'Centre fermé';
  if (block.scopeType === 'lane') return `Piste ${block.scopeRef} bloquée`;
  if (block.scopeType === 'activity') return `${availabilityActivityLabel(block.scopeRef)} bloqué`;
  if (block.scopeType === 'formula') return `${availabilityFormulaLabel(block.scopeRef)} bloquée`;
  return 'Blocage';
}

function availabilityTimeText(block) {
  const start = availabilityBlockStartMin(block);
  const end = availabilityBlockEndMin(block);
  if (start === null && end === null) return '(toute la journée)';
  if (start === null || end === null) return '';
  return `${availabilityMinutesToHHMM(start)}-${availabilityMinutesToHHMM(end)}`;
}

async function loadAvailabilityBlocks(force = false) {
  if (availabilityBlocksCache.loading) return;
  if (availabilityBlocksCache.loaded && !force) return;
  if (!canUseStaffPermission('settings.manage')) return;
  availabilityBlocksCache.loading = true;
  if (force) availabilityBlocksCache.error = '';
  try {
    const centerId = getCurrentStaffCenterId();
    const response = await apiRequest(`${API_ENDPOINTS.ops}?action=listAvailabilityBlocks&centerId=${encodeURIComponent(centerId)}`);
    availabilityBlocksCache = {
      loaded: true,
      loading: false,
      error: '',
      blocks: Array.isArray(response.blocks) ? response.blocks : []
    };
  } catch (error) {
    availabilityBlocksCache.loading = false;
    availabilityBlocksCache.loaded = true;
    availabilityBlocksCache.error = error?.message || 'Lecture des blocages impossible.';
  }
  refreshAvailabilityBlocksUi();
}

// Charge une seule fois pour le planning (center-wide, filtre client par date).
function ensureAvailabilityBlocksForPlanning() {
  if (!canUseStaffPermission('settings.manage')) return;
  if (availabilityBlocksCache.loaded || availabilityBlocksCache.loading) return;
  loadAvailabilityBlocks(false);
}

function refreshAvailabilityBlocksUi() {
  const list = document.getElementById('avbList');
  if (list) list.innerHTML = renderAvailabilityBlocksList();
  if (document.querySelector('[data-estab-page]')) ebRefresh();
  if (state.view === 'staff') {
    renderBandeauPrivatisations();
    if (document.getElementById('planningGridWrap')) renderPlanning();
    if (document.getElementById('laserPlanningGridWrap')) renderLaserPlanning();
    renderGlobalPlanningSurface();
    // Les pistes libres maintenant attendaient les blocages : elles se disent
    // des qu ils arrivent.
    if (isStaffPlanningPageActive()) renderKpis();
  }
}

function getAvailabilityBlocksForDate(dateStr) {
  if (!dateStr) return [];
  // (la journee servie par staff-state, deja resolue, fait foi : elle suit les autres postes)
  const servies = fermeturesServies(dateStr);
  if (servies) return servies;
  const blocks = availabilityBlocksCache.blocks || [];
  const dow = parseLocalDate(dateStr).getDay();
  return blocks.filter(block => {
    if (block.recurrence === 'weekly') {
      if (Number(block.dayOfWeek) !== dow) return false;
      if (block.dateFrom && dateStr < block.dateFrom) return false;
      if (block.dateUntil && dateStr > block.dateUntil) return false;
      return true;
    }
    return block.date === dateStr;
  });
}

// Fenetres de blocage bowling (heures decimales) par piste, pour le jour
// affiche. center + activite bowling => toutes les pistes ; lane => la piste ;
// formula => pas de piste physique (non marque ici). Jour entier => plage
// complete d'ouverture.
function getBowlingBlockWindows(dateStr, openHour, closeHour) {
  const perLane = {};
  const push = (lane, win) => { (perLane[lane] = perLane[lane] || []).push(win); };
  const toWindow = (block) => {
    const startMin = availabilityBlockStartMin(block);
    const endMin = availabilityBlockEndMin(block);
    const full = startMin === null && endMin === null;
    const startH = full ? openHour : Math.max(openHour, startMin / 60);
    const endH = full ? closeHour : Math.min(closeHour, endMin / 60);
    const prive = block.kind === 'private';
    return { startH, endH, reason: prive ? `Privatisé : ${block.reason || 'groupe privé'}` : block.reason || '', full, prive };
  };
  // Un blocage de tout le centre couvre SES pistes : a 12 pistes, les pistes
  // 9 a 12 restaient ouvertes a la vente sous un « centre fermé ».
  const laneCount = getAvailabilityLaneCount();
  getAvailabilityBlocksForDate(dateStr).forEach(block => {
    if (block.scopeType === 'center' || (block.scopeType === 'activity' && (block.scopeRef === 'bowling' || block.scopeRef === 'duckpin_bowling'))) {
      for (let lane = 1; lane <= laneCount; lane += 1) push(lane, toWindow(block));
    } else if (block.scopeType === 'lane') {
      const lane = Number(block.scopeRef);
      if (Number.isFinite(lane) && lane >= 1 && lane <= laneCount) push(lane, toWindow(block));
    }
  });
  Object.keys(perLane).forEach(key => {
    perLane[key] = perLane[key].filter(win => win.endH > win.startH && win.endH > openHour && win.startH < closeHour);
    if (!perLane[key].length) delete perLane[key];
  });
  return perLane;
}

// Banniere laser : le planning laser est un agenda (pas une grille par piste),
// on signale donc au niveau du jour les blocages laser/centre actifs.
function renderLaserBlockBanner(dateStr) {
  if (!availabilityBlocksCache.loaded) return '';
  const blocks = getAvailabilityBlocksForDate(dateStr).filter(block =>
    block.scopeType === 'center' || (block.scopeType === 'activity' && block.scopeRef === 'laser_game'));
  if (!blocks.length) return '';
  const items = blocks.map(block => {
    const scope = block.scopeType === 'center' ? 'Centre ferme' : 'Laser Game bloque';
    const time = availabilityTimeText(block) || '(toute la journée)';
    const reason = block.reason ? ` (${escapeHtml(block.reason)})` : '';
    return `<li data-blocked-laser="1">${escapeHtml(scope)} ${escapeHtml(time)}${reason}</li>`;
  }).join('');
  return `<div class="planning-blocked-banner" role="status"><strong>Blocage actif ce jour</strong><ul>${items}</ul></div>`;
}

// Quand une fermeture s applique, dit comme au comptoir : « le samedi 15 août, toute la journée ».
function availabilityQuandLisible(block) {
  const jour = (iso, options) => {
    const d = new Date(`${iso}T12:00:00`);
    if (Number.isNaN(d.getTime())) return String(iso || '');
    return d.toLocaleDateString('fr-BE', { ...options, ...(d.getFullYear() !== new Date().getFullYear() ? { year: 'numeric' } : {}) });
  };
  const start = availabilityBlockStartMin(block);
  const end = availabilityBlockEndMin(block);
  const heures = start === null && end === null ? 'toute la journée'
    : start === null || end === null ? '' : `de ${availabilityMinutesToHHMM(start)} à ${end >= 1440 ? 'minuit' : availabilityMinutesToHHMM(end)}`;
  let quand;
  if (block.recurrence === 'weekly') {
    const court = iso => jour(iso, { day: 'numeric', month: 'long' });
    quand = `tous les ${AVAILABILITY_DAY_NAMES[Number(block.dayOfWeek)] || 'jour'}s`;
    if (block.dateFrom && block.dateUntil) quand += ` du ${court(block.dateFrom)} au ${court(block.dateUntil)}`;
    else if (block.dateFrom) quand += ` à partir du ${court(block.dateFrom)}`;
    else if (block.dateUntil) quand += ` jusqu’au ${court(block.dateUntil)}`;
  } else {
    quand = `le ${jour(block.date || '', { weekday: 'long', day: 'numeric', month: 'long' })}`;
  }
  return heures ? `${quand}, ${heures}` : quand;
}

// Les fermetures decidees : quoi, quand, puis le motif. Les dates dans l ordre, les fermetures de chaque semaine apres.
function renderAvailabilityBlocksList() {
  if (availabilityBlocksCache.loading && !availabilityBlocksCache.loaded) {
    return '<div class="availability-empty">Lecture des fermetures…</div>';
  }
  if (availabilityBlocksCache.error) {
    return `<div class="availability-empty availability-error">${escapeHtml(availabilityBlocksCache.error)} <button type="button" class="btn btn-secondary btn-sm" onclick="loadAvailabilityBlocks(true)">Réessayer</button></div>`;
  }
  const cle = block => (block.recurrence === 'weekly' ? `2${block.dateFrom || ''}` : `1${block.date || ''}`);
  const tous = (availabilityBlocksCache.blocks || []).slice().sort((a, b) => (cle(a) < cle(b) ? -1 : cle(a) > cle(b) ? 1 : 0));
  // (une privatisation se lit et se retire en entier : une ligne pour ses blocages, « Retirer » les retire tous)
  const blocks = tous.filter(block => block.kind !== 'private');
  const privatisations = privatisationsGroupees(tous);
  if (!blocks.length && !privatisations.length) {
    return '<div class="availability-empty">Aucune fermeture décidée. Le centre suit ses horaires.</div>';
  }
  const lignesPrivees = privatisations.map(p => `<li class="availability-item is-prive" data-privatisation="${escapeHtml(p.ids.join(','))}"><span class="availability-item-body"><span class="availability-item-label">${escapeHtml(`Privatisé : ${p.nom || 'groupe privé'}, ${availabilityQuandLisible(p.bloc)}`)}</span><span class="availability-item-reason">${escapeHtml(privatisationPortee(p))}</span></span><button type="button" class="availability-del" onclick="retirerPrivatisationUi('${escapeJsString(p.ids.join(','))}')">Retirer</button></li>`).join('');
  return `<ul class="availability-list">${blocks.map(block => `<li class="availability-item" data-block-id="${escapeHtml(String(block.id))}"><span class="availability-item-body"><span class="availability-item-label">${escapeHtml(`${availabilityScopeText(block)} ${availabilityQuandLisible(block)}`)}</span>${block.reason ? `<span class="availability-item-reason">${escapeHtml(block.reason)}</span>` : ''}</span><button type="button" class="availability-del" onclick="deleteAvailabilityBlockUi(${Number(block.id)})">Retirer</button></li>`).join('')}${lignesPrivees}</ul>`;
}

function updateAvailabilityFormVisibility() {
  const scope = document.getElementById('avb-scope')?.value || 'center';
  const recurrence = document.getElementById('avb-recurrence')?.value || 'once';
  const setDisplay = (selector, on) => document.querySelectorAll(selector).forEach(el => { el.style.display = on ? '' : 'none'; });
  setDisplay('.avb-cond-lane', scope === 'lane');
  setDisplay('.avb-cond-activity', scope === 'activity');
  setDisplay('.avb-cond-formula', scope === 'formula');
  setDisplay('.avb-cond-once', recurrence === 'once');
  setDisplay('.avb-cond-weekly', recurrence === 'weekly');
}

function resetAvailabilityForm() {
  ['avb-date', 'avb-from', 'avb-until', 'avb-start', 'avb-end', 'avb-reason'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
}

async function submitAvailabilityBlock() {
  if (!canUseStaffPermission('settings.manage')) { toast('Réservé à la direction.'); return; }
  const value = id => (document.getElementById(id)?.value || '').trim();
  const scopeType = value('avb-scope') || 'center';
  const recurrence = value('avb-recurrence') || 'once';
  // Le centre affiche : le serveur verifie le droit de le viser. Sans lui, le blocage tombait au centre de connexion.
  const body = { action: 'saveAvailabilityBlock', centerId: getCurrentStaffCenterId(), scopeType, recurrence };
  if (scopeType === 'lane') {
    const lane = value('avb-lane');
    if (!lane) { toast('Choisissez une piste.'); return; }
    body.scopeRef = lane;
  } else if (scopeType === 'activity') {
    const activity = value('avb-activity');
    if (!activity) { toast('Choisissez une activité.'); return; }
    body.scopeRef = activity;
  } else if (scopeType === 'formula') {
    const formula = value('avb-formula');
    if (!formula) { toast('Choisissez une formule.'); return; }
    body.scopeRef = formula;
  }
  if (recurrence === 'once') {
    const date = value('avb-date');
    if (!date) { toast('Choisissez une date.'); return; }
    body.date = date;
  } else {
    body.dayOfWeek = Number(value('avb-dow'));
    const from = value('avb-from');
    const until = value('avb-until');
    if (from) body.dateFrom = from;
    if (until) body.dateUntil = until;
  }
  const start = value('avb-start');
  const end = value('avb-end');
  if ((start && !end) || (!start && end)) { toast('Renseignez les deux heures, ou aucune.'); return; }
  if (start && end) {
    if (end <= start) { toast("L'heure de fin doit suivre le début."); return; }
    body.startTime = start;
    body.endTime = end;
  }
  const reason = value('avb-reason');
  if (reason) body.reason = reason;
  const submitBtn = document.getElementById('avbSubmit');
  const libelle = submitBtn ? submitBtn.textContent : '';
  if (submitBtn) { submitBtn.disabled = true; submitBtn.textContent = 'Envoi…'; }
  try {
    await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify(body) });
    toast('Fermeture programmée.');
    resetAvailabilityForm();
    await loadAvailabilityBlocks(true);
  } catch (error) {
    toast(error?.message || 'Fermeture impossible.');
  } finally {
    const btn = document.getElementById('avbSubmit');
    if (btn) { btn.disabled = false; btn.textContent = libelle || 'Programmer'; }
  }
}

async function deleteAvailabilityBlockUi(id) {
  if (!canUseStaffPermission('settings.manage')) { toast('Réservé à la direction.'); return; }
  const block = (availabilityBlocksCache.blocks || []).find(item => Number(item.id) === Number(id));
  const label = block ? `${availabilityScopeText(block)} ${availabilityQuandLisible(block)}` : '';
  if (!window.confirm(label ? `Retirer cette fermeture ?\n${label}` : 'Retirer cette fermeture ?')) return;
  try {
    await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'deleteAvailabilityBlock', centerId: getCurrentStaffCenterId(), id: Number(id) }) });
    toast('Fermeture retirée.');
    await loadAvailabilityBlocks(true);
  } catch (error) {
    toast(error?.message || 'Suppression impossible.');
  }
}

// ── LA PRIVATISATION (2026-11-18) ────────────────────────────────────────────
// Marius (Gembloux) : « est-ce que tu as prévu un onglet privatisation ? Genre comme ça je suis
// sûr que personne ne rajoute de réservation à ce moment-là ». Une privatisation est une fermeture
// nommee (availability_blocks, kind 'private') que le serveur fait respecter partout : en ligne, au
// comptoir et dans sa simulation, au glisser, dans l assistant. La console la montre, la pose et
// la retire ; le droit est juge par le serveur (api/ops.js), GESTES_STAFF.privatiser ne fait que
// cacher ce qui serait refuse.

// Les privatisations d une liste de blocages, une par groupe pose ensemble : meme jour, meme plage,
// meme nom, meme dossier (le regroupement de lib/privatisation.js privatisationsDuJour).
function privatisationsGroupees(blocs, dateStr = '') {
  const groupes = new Map();
  const vus = new Set();
  (Array.isArray(blocs) ? blocs : []).forEach(b => {
    if (!b || b.kind !== 'private' || vus.has(Number(b.id))) return;
    vus.add(Number(b.id));
    const debut = availabilityBlockStartMin(b);
    const fin = availabilityBlockEndMin(b);
    const jour = b.date || dateStr;
    const cle = [jour, debut, fin, b.reason || '', b.reservationId || ''].join('|');
    if (!groupes.has(cle)) groupes.set(cle, { ids: [], nom: String(b.reason || ''), date: jour, debut, fin, toutLeCentre: false, activites: [], reservationId: b.reservationId || null, bloc: b });
    const groupe = groupes.get(cle);
    groupe.ids.push(Number(b.id));
    if (b.scopeType === 'center') groupe.toutLeCentre = true;
    else if (b.scopeType === 'activity' && b.scopeRef && !groupe.activites.includes(String(b.scopeRef))) groupe.activites.push(String(b.scopeRef));
  });
  return [...groupes.values()].sort((a, b) => String(a.date).localeCompare(String(b.date)) || (a.debut ?? 0) - (b.debut ?? 0) || a.nom.localeCompare(b.nom));
}

function privatisationPlage(p) {
  if (p.debut == null && p.fin == null) return 'toute la journée';
  const fin = p.fin == null || p.fin >= 1440 ? 'minuit' : availabilityMinutesToHHMM(p.fin);
  return `de ${availabilityMinutesToHHMM(p.debut ?? 0)} à ${fin}`;
}

function privatisationPortee(p) {
  return p.toutLeCentre ? 'Tout le centre' : p.activites.map(id => rvNomActivite(id)).join(', ');
}

// La phrase du serveur (lib/availability-blocks.js phraseDuBlocage) : « Privatisé : Dupont, de 18:00 à 22:00 ».
function privatisationPhrase(p) {
  return `Privatisé : ${p.nom || 'groupe privé'}, ${privatisationPlage(p)}`;
}

// LE BANDEAU, sous la barre des trois plannings : chaque privatisation du jour, ce qu elle ferme,
// le dossier du groupe (il s ouvre d un toucher), « Modifier » et « Retirer » pour qui peut
// privatiser. Une journee sans privatisation ne le montre pas : le planning reste celui d avant.
function renderBandeauPrivatisations() {
  if (typeof document === 'undefined') return;
  const zone = document.getElementById('planningPrivatisations');
  if (!zone) return;
  const liste = state.view === 'staff' ? privatisationsGroupees(getAvailabilityBlocksForDate(state.currentDate), state.currentDate) : [];
  const peut = peutGeste('privatiser');
  const cadenas = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4.5" y="10.5" width="15" height="10" rx="2"/><path d="M8 10.5V7.5a4 4 0 0 1 8 0v3"/></svg>';
  const html = liste.map(p => {
    const groupe = p.reservationId ? todaysReservations().find(r => Number(r.id) === Number(p.reservationId)) : null;
    const dossier = groupe ? `<button type="button" class="pb-prive__dossier" onclick="openPos(${Number(groupe.id)})">${escapeHtml(groupe.name || `Dossier n° ${groupe.id}`)}</button>` : '';
    const gestes = peut
      ? `<span class="pb-prive__gestes"><button type="button" class="pb-prive__b" onclick="modifierPrivatisationUi('${escapeJsString(p.ids.join(','))}')">Modifier</button><button type="button" class="pb-prive__x" onclick="retirerPrivatisationUi('${escapeJsString(p.ids.join(','))}')">Retirer</button></span>`
      : '';
    return `<div class="pb-prive" data-privatisation="${escapeHtml(p.ids.join(','))}"><span class="pb-prive__cadenas" aria-hidden="true">${cadenas}</span><span class="pb-prive__t"><b>${escapeHtml(privatisationPhrase(p))}</b><span>${escapeHtml(privatisationPortee(p))}${dossier}</span></span>${gestes}</div>`;
  }).join('');
  if (zone.__rendu === html) return;
  zone.__rendu = html;
  zone.innerHTML = html;
  zone.hidden = !liste.length;
}

// Apres une ecriture : la journee se relit (staff-state sert les privatisations a chaque poste), et
// la liste d Etablissement aussi quand elle est chargee.
async function privatisationRelire(date) {
  try {
    await syncDateReservations(date || state.currentDate, { silent: true });
  } catch (error) {
    // (la lecture suivante du planning reprendra la journee)
  }
  if (availabilityBlocksCache.loaded) await loadAvailabilityBlocks(true);
  else refreshAvailabilityBlocksUi();
}

// Les privatisations a venir du centre, telles que le serveur les liste (action listerPrivatisations) :
// la fenetre « Privatisations à venir » les montre, la fenetre Privatiser y lit les autres groupes du
// jour choisi, « Modifier » y retrouve une privatisation d un autre jour.
let privatisationsAVenir = null;
async function lirePrivatisationsAVenir() {
  const reponse = await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'listerPrivatisations', centerId: getCurrentStaffCenterId() }) });
  privatisationsAVenir = Array.isArray(reponse && reponse.privatisations) ? reponse.privatisations : [];
  return privatisationsAVenir;
}

function privatisationDeLaListe(x) {
  const minutes = (h) => { const [a, b] = String(h || '').split(':').map(Number); return (a || 0) * 60 + (b || 0); };
  return {
    ids: (x.ids || []).map(Number),
    nom: String(x.nom || ''),
    date: x.date,
    debut: minutes(x.startTime),
    fin: x.endTime === '24:00' ? 1440 : minutes(x.endTime),
    toutLeCentre: Boolean(x.toutLeCentre),
    activites: (x.activites || []).map(a => String((a && a.id) || a)),
    reservationId: x.reservationId || null,
  };
}

// Une privatisation connue de ce poste, par les numeros de ses blocages : la journee servie, les
// blocages d Etablissement, ou la derniere liste des privatisations a venir.
function privatisationConnue(ids) {
  const voulus = (ids || []).map(Number);
  const blocs = [...(fermeturesServies(state.currentDate) || []), ...(availabilityBlocksCache.blocks || [])].filter(b => voulus.includes(Number(b.id)));
  const groupe = privatisationsGroupees(blocs, state.currentDate)[0];
  if (groupe) return groupe;
  const lue = (privatisationsAVenir || []).find(x => (x.ids || []).some(id => voulus.includes(Number(id))));
  return lue ? privatisationDeLaListe(lue) : null;
}
const idsDuTexte = (texte) => String(texte || '').split(',').map(Number).filter(n => Number.isInteger(n) && n > 0);

async function retirerPrivatisationUi(idsTexte) {
  if (!peutGeste('privatiser')) { toast('Votre rôle ne permet pas de retirer une privatisation. Demandez à un responsable.'); return; }
  const ids = idsDuTexte(idsTexte);
  if (!ids.length) return;
  const p = privatisationConnue(ids);
  const voulu = await staffConfirm({
    title: 'Retirer cette privatisation ?',
    body: `${p ? `${privatisationPhrase(p)} (${privatisationPortee(p)}). ` : ''}Ces heures redeviendront réservables, en ligne et au comptoir.`,
    confirmLabel: 'Retirer',
    danger: true,
  });
  if (!voulu) return;
  try {
    await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'retirerPrivatisation', centerId: getCurrentStaffCenterId(), ids }) });
    toast('Privatisation retirée.');
  } catch (error) {
    toast(error?.message || 'Retrait impossible pour le moment. Réessayez.');
  }
  await privatisationRelire(p ? p.date : state.currentDate);
  if (document.getElementById('prvListe')) chargerListePrivatisations();
}

// « Modifier » (le bandeau, la liste) : la fenetre de la privatisation, remplie. Elle s enregistre
// a la place de l ancienne, en une ecriture (le serveur retire et pose ensemble).
function modifierPrivatisationUi(idsTexte, { depuisLaListe = false } = {}) {
  const p = privatisationConnue(idsDuTexte(idsTexte));
  if (!p) { toast('Cette privatisation a changé : le planning se met à jour.'); privatisationRelire(state.currentDate); return; }
  ouvrirPrivatiser({
    remplace: p.ids,
    date: p.date,
    debut: availabilityMinutesToHHMM(p.debut ?? 0),
    fin: p.fin == null || p.fin >= 1440 ? '00:00' : availabilityMinutesToHHMM(p.fin),
    nom: p.nom,
    toutLeCentre: p.toutLeCentre,
    activites: p.activites,
    reservationId: p.reservationId,
    depuisLaListe,
  });
}

// ── LA FENETRE « PRIVATISER » (refaite le 2026-11-20, Ansar : « un truc bcp plus complet, bcp
// plus beau visuellement ») ───────────────────────────────────────────────────────────────────
// A gauche ce qu on decide : le jour (une puce par jour, ou un autre), les heures (la journee
// dessinee avec ses reservations, la plage se tire a la souris ou au doigt, ou se tape), ce qui est
// ferme (tout le centre, ou des activites, chacune avec sa photo), pour qui. A droite ce que ca
// donne, en direct : la plage en clair, la phrase que le planning dira, et les reservations deja sur
// ces heures, lues par le serveur a chaque changement (a blanc, rien ne s ecrit). Plus d etape
// « voir ce qui est deja reserve » : « Privatiser » s allume quand la liste lue est celle de la
// demande. Rien ne se deplace tout seul, et l une des reservations peut etre le dossier du groupe.
let prv = null;
const PRV_PAS = 15;

function privatiserActivites() {
  const ids = [...new Set((typeof getCenterActivities === 'function' ? getCenterActivities() : []).map(a => String((a && a.id) || '')).filter(Boolean))];
  return (ids.length ? ids : ['bowling', 'laser_game']).map(id => ({ id, nom: rvNomActivite(id) }));
}

// Les heures d ouverture du jour, en minutes (getSchedule rend des heures decimales). Un jour ferme
// garde une journee de 10:00 a minuit, et le dit.
function privatiserOuverture(date) {
  let plage = null;
  try { plage = typeof getSchedule === 'function' ? getSchedule(date, state.isHolidayMode) : null; } catch (error) { plage = null; }
  const open = plage && Number.isFinite(Number(plage.open)) ? Math.round(Number(plage.open) * 60) : 600;
  const close = plage && Number.isFinite(Number(plage.close)) ? Math.round(Number(plage.close) * 60) : 1440;
  const o = Math.max(0, Math.min(open, 1380));
  return { open: o, close: Math.max(o + 60, Math.min(close, 1440)), ferme: !plage };
}

const prvMinutes = (h) => {
  const lu = /^(\d{1,2}):(\d{2})$/.exec(String(h || '').trim());
  return lu ? Number(lu[1]) * 60 + Number(lu[2]) : null;
};
const prvHeure = (m) => (m >= 1440 ? '00:00' : availabilityMinutesToHHMM(Math.max(0, Math.round(m))));
const prvHeureDite = (m) => (m >= 1440 ? 'minuit' : availabilityMinutesToHHMM(Math.max(0, Math.round(m))));
function prvDuree(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return h && m ? `${h} h ${String(m).padStart(2, '0')}` : h ? `${h} h` : `${m} min`;
}
// (une date en morceaux, pour les puces des jours ; rsDateLue garde ses propres formats)
const prvDatesMemo = new Map();
function prvDate(iso, options) {
  const cle = `${iso}|${JSON.stringify(options)}`;
  if (!prvDatesMemo.has(cle)) {
    let texte = iso;
    try { texte = new Intl.DateTimeFormat('fr-BE', options).format(parseLocalDate(iso)); } catch (error) { /* date brute */ }
    prvDatesMemo.set(cle, texte.replace('.', ''));
  }
  return prvDatesMemo.get(cle);
}
const prvDateLongue = (iso) => rsDateLue(iso, { weekday: 'long', day: 'numeric', month: 'long' });

// Les jours proposes en puces : aujourd hui et les 13 suivants, plus le jour choisi s il est plus loin.
function privatiserJours(choisi) {
  const jours = [];
  const d = parseLocalDate(todayStr());
  for (let i = 0; i < 14; i += 1) {
    jours.push(rvIso(d));
    d.setDate(d.getDate() + 1);
  }
  if (choisi && !jours.includes(choisi) && choisi >= todayStr()) jours.push(choisi);
  return jours;
}

function privatiserJoursHtml(choisi) {
  return privatiserJours(choisi).map((iso, i) => {
    const on = iso === choisi;
    return `<button type="button" class="prv-jour${on ? ' is-on' : ''}" role="radio" aria-checked="${on}" aria-label="${escapeHtml(prvDateLongue(iso))}" data-prv-jour="${escapeHtml(iso)}" onclick="privatiserJour('${escapeJsString(iso)}')"><span>${escapeHtml(i === 0 ? 'auj' : prvDate(iso, { weekday: 'short' }))}</span><b>${escapeHtml(prvDate(iso, { day: 'numeric' }))}</b><small>${escapeHtml(prvDate(iso, { month: 'short' }))}</small></button>`;
  }).join('');
}

function privatiserCorpsHtml({ jour, debut, fin, nom, toutLeCentre, activites, modifier }) {
  const centre = getCurrentStaffCenterId();
  const acts = privatiserActivites().map(a => {
    const coche = !toutLeCentre && activites.includes(a.id);
    return `<label class="prv-act${coche ? ' is-on' : ''}"><input type="checkbox" name="prvActivite" value="${escapeHtml(a.id)}"${coche ? ' checked' : ''} onchange="privatiserChange('activite')">${ficheVisuelActivite({ centerId: centre }, { activityId: a.id, nom: a.nom })}<span class="prv-act__nom">${escapeHtml(a.nom)}</span></label>`;
  }).join('');
  const signe = (plus) => `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><path d="${plus ? 'M5 12h14M12 5v14' : 'M5 12h14'}"/></svg>`;
  const heure = (id, dit, valeur) => `<div class="prv-heure"><span class="prv-heure__dit" id="${id}Dit">${dit}</span><button type="button" class="prv-pas" aria-label="${dit} : 15 minutes plus tôt" onclick="privatiserPas('${id}', -1)">${signe(false)}</button><input class="prv-heure__h" id="${id}" type="time" step="900" required value="${escapeHtml(valeur)}" aria-labelledby="${id}Dit" oninput="privatiserChange()"><button type="button" class="prv-pas" aria-label="${dit} : 15 minutes plus tard" onclick="privatiserPas('${id}', 1)">${signe(true)}</button></div>`;
  return `<form class="prv2" id="prvForm" onsubmit="privatiserEnvoyer(event)" novalidate>
    <div class="prv2-gauche">
      <section class="prv-bloc" aria-labelledby="prvJourT">
        <h4 class="prv-tit" id="prvJourT">Le jour</h4>
        <div class="prv-jours" id="prvJours" role="radiogroup" aria-labelledby="prvJourT">${privatiserJoursHtml(jour)}</div>
        <label class="prv-autre"><span>Un autre jour</span><input class="input" id="prvDate" type="date" required value="${escapeHtml(jour)}" min="${escapeHtml(todayStr())}" oninput="privatiserChange('jour')"></label>
      </section>
      <section class="prv-bloc" aria-labelledby="prvHeuresT">
        <h4 class="prv-tit" id="prvHeuresT">Les heures</h4>
        <div class="prv-jauge" aria-hidden="true">
          <div class="prv-jauge__piste" id="prvPiste">
            <div class="prv-jauge__privees" id="prvJaugePrivees"></div>
            <div class="prv-jauge__resas" id="prvJaugeResas"></div>
            <div class="prv-jauge__sel" id="prvJaugeSel" data-prv-tirer="tout"><span class="prv-poignee" data-prv-tirer="debut"></span><span class="prv-poignee" data-prv-tirer="fin"></span></div>
          </div>
          <div class="prv-jauge__heures" id="prvJaugeHeures"></div>
        </div>
        <p class="prv-aide prv-ferme" id="prvFerme" hidden>Le centre est fermé ce jour-là.</p>
        <div class="prv-heures">${heure('prvDe', 'De', debut)}${heure('prvA', 'À', fin)}<p class="prv-duree" id="prvDuree"></p></div>
        <div class="prv-raccourcis" id="prvRaccourcis"></div>
      </section>
      <section class="prv-bloc" aria-labelledby="prvQuoiT">
        <h4 class="prv-tit" id="prvQuoiT">Ce qui est fermé</h4>
        <div class="prv-seg" role="radiogroup" aria-labelledby="prvQuoiT">
          <label class="prv-seg__b"><input type="radio" name="prvQuoi" value="centre"${toutLeCentre ? ' checked' : ''} onchange="privatiserChange('centre')"><span>Tout le centre</span></label>
          <label class="prv-seg__b"><input type="radio" name="prvQuoi" value="activites"${toutLeCentre ? '' : ' checked'} onchange="privatiserChange()"><span>Des activités</span></label>
        </div>
        <div class="prv-acts" id="prvActs"${toutLeCentre ? ' hidden' : ''}>${acts}</div>
      </section>
      <section class="prv-bloc">
        <label class="prv-tit" for="prvNom">Pour qui</label>
        <input class="input prv-nom" id="prvNom" maxlength="120" autocomplete="off" required placeholder="Anniversaire Dupont, société Lambert" value="${escapeHtml(nom)}" oninput="privatiserChange('nom')">
        <p class="prv-aide">L’équipe lit ce nom sur le planning. En ligne, les clients lisent seulement « privatisé ».</p>
      </section>
    </div>
    <aside class="prv2-droite" aria-label="Ce que donne la privatisation">
      <div class="prv-resume" id="prvResume"></div>
      <div class="prv-vu" id="prvVu" aria-live="polite"></div>
    </aside>
    <div class="prv2-pied">
      <p class="bdg-hf-err" id="prvErr" role="alert" hidden></p>
      <div class="bdg-actions">
        <button type="button" class="bdg-b" onclick="privatiserAnnuler()">Annuler</button>
        <button type="submit" class="bdg-p" id="prvOk" disabled>${modifier ? 'Enregistrer' : 'Privatiser'}</button>
      </div>
    </div>
  </form>`;
}

function ouvrirPrivatiser({ date = '', debut = '', fin = '', nom = '', toutLeCentre = true, activites = [], reservationId = null, remplace = [], depuisLaListe = false } = {}) {
  if (!peutGeste('privatiser')) { toast('Votre rôle ne permet pas de privatiser. Demandez à un responsable.'); return; }
  const jour = date && date >= todayStr() ? date : (state.currentDate >= todayStr() ? state.currentDate : todayStr());
  const plage = privatiserOuverture(jour);
  // (sans heures donnees : la soiree, de 18:00 a la fermeture, ce qui se privatise le plus souvent)
  const soir = Math.min(Math.max(18 * 60, plage.open), plage.close - 60);
  const etat = {
    remplace: (remplace || []).map(Number).filter(n => n > 0),
    reservationId: reservationId ? Number(reservationId) : null,
    depuisLaListe,
    vu: null,
    ticket: 0,
    ticketJour: 0,
    minuterie: 0,
    journee: { date: jour, plage, resas: [] },
  };
  const parActivites = toutLeCentre === false && (activites || []).length > 0;
  // (l etat se pose apres l ouverture : la fenetre d avant, fermee par celle-ci, ne l efface pas)
  smFenetreOuvrir({
    titre: etat.remplace.length ? 'Modifier la privatisation' : 'Privatiser',
    sous: 'Personne ne pourra réserver sur ces heures, ni en ligne ni au comptoir.',
    classe: 'prv-fen',
    corps: privatiserCorpsHtml({ jour, debut: debut || prvHeure(soir), fin: fin || prvHeure(plage.close), nom, toutLeCentre: !parActivites, activites: activites || [], modifier: etat.remplace.length > 0 }),
    quandFermee: () => { clearTimeout(etat.minuterie); if (prv === etat) prv = null; },
  });
  prv = etat;
  const piste = document.getElementById('prvPiste');
  if (piste) piste.addEventListener('pointerdown', privatiserTirer);
  document.querySelector('#prvJours .is-on')?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  privatiserJournee(jour);
  privatiserPeindre();
  privatiserVerifier();
  // (les autres groupes des autres jours, pour la journee dessinee)
  lirePrivatisationsAVenir().then(() => privatiserPeindre()).catch(() => {});
}

function privatiserAnnuler() {
  const retour = prv && prv.depuisLaListe;
  smFenetreFermer();
  if (retour) ouvrirListePrivatisations();
}

function privatiserErreur(message) {
  const zone = document.getElementById('prvErr');
  if (!zone) { if (message) toast(message); return; }
  zone.textContent = message || '';
  zone.hidden = !message;
}

function privatiserLire() {
  const valeur = id => (document.getElementById(id)?.value || '').trim();
  const toutLeCentre = (document.querySelector('input[name="prvQuoi"]:checked') || {}).value !== 'activites';
  const activites = toutLeCentre ? [] : [...document.querySelectorAll('input[name="prvActivite"]:checked')].map(c => c.value);
  // (« À 00:00 » veut dire jusqu a minuit)
  const fin = valeur('prvA');
  return { date: valeur('prvDate'), startTime: valeur('prvDe'), endTime: fin === '00:00' ? '24:00' : fin, toutLeCentre, activites, nom: valeur('prvNom') };
}

// Ce qui manque a la demande, dans l ordre ou elle se lit. `pourVoir` : la liste se lit sans le nom.
function privatiserManque(corps, { pourVoir = false } = {}) {
  const debut = prvMinutes(corps.startTime);
  const fin = corps.endTime === '24:00' ? 1440 : prvMinutes(corps.endTime);
  if (!corps.date) return 'Choisissez le jour.';
  if (debut === null || fin === null) return 'Choisissez de quelle heure à quelle heure.';
  if (!(fin > debut)) return 'L’heure de fin vient après l’heure de début.';
  if (!corps.toutLeCentre && !corps.activites.length) return 'Choisissez au moins une activité, ou tout le centre.';
  if (!pourVoir && !corps.nom) return 'Donnez le nom du client ou de l’événement.';
  return '';
}

// La cle d une demande pour la liste lue : le nom n y change rien.
const privatiserCle = (corps) => JSON.stringify({ ...corps, nom: '' });

// La demande change : ce qui a ete lu ne vaut plus pour elle, la liste se relit un instant apres.
function privatiserChange(quoi = '') {
  if (!prv) return;
  if (quoi === 'centre') document.querySelectorAll('input[name="prvActivite"]').forEach(c => { c.checked = false; });
  const acts = document.getElementById('prvActs');
  const parActivites = (document.querySelector('input[name="prvQuoi"]:checked') || {}).value === 'activites';
  if (acts) acts.hidden = !parActivites;
  document.querySelectorAll('.prv-act').forEach(l => l.classList.toggle('is-on', Boolean(l.querySelector('input:checked'))));
  if (quoi === 'jour') {
    const date = document.getElementById('prvDate')?.value || '';
    const zone = document.getElementById('prvJours');
    if (zone && date) {
      zone.innerHTML = privatiserJoursHtml(date);
      zone.querySelector('.is-on')?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    }
    if (date && (!prv.journee || prv.journee.date !== date)) privatiserJournee(date);
  }
  privatiserErreur('');
  privatiserPeindre();
  if (quoi === 'nom') { privatiserBouton(); return; }
  prv.vu = null;
  // (une lecture deja partie ne vaut plus : sa reponse ne s affichera pas)
  prv.ticket += 1;
  privatiserBouton();
  clearTimeout(prv.minuterie);
  prv.minuterie = setTimeout(privatiserVerifier, 250);
}

function privatiserJour(iso) {
  const champ = document.getElementById('prvDate');
  if (!champ || !iso) return;
  champ.value = iso;
  privatiserChange('jour');
}

function privatiserPas(id, sens) {
  const champ = document.getElementById(id);
  if (!champ || !prv) return;
  const ouvert = prv.journee.plage;
  const actuel = prvMinutes(champ.value === '00:00' && id === 'prvA' ? '24:00' : champ.value);
  const base = actuel === null ? (id === 'prvDe' ? ouvert.open : ouvert.close) : actuel;
  const pas = Math.round((base + sens * PRV_PAS) / PRV_PAS) * PRV_PAS;
  champ.value = prvHeure(Math.max(0, Math.min(1440, pas)));
  privatiserChange();
}

// LA JAUGE : la journee, de l ouverture a la fermeture (elargie si la plage en sort). Les
// reservations du jour en traits, rangees sur autant de lignes qu il faut pour ne jamais se cacher ;
// celles que la plage ferme, en fonce ; les autres privatisations du jour, hachurees.
function privatiserBornes() {
  const corps = privatiserLire();
  const plage = prv.journee.plage;
  const debut = prvMinutes(corps.startTime);
  const fin = corps.endTime === '24:00' ? 1440 : prvMinutes(corps.endTime);
  const min = Math.min(plage.open, debut ?? plage.open);
  const max = Math.max(plage.close, fin ?? plage.close);
  return { corps, debut, fin, min: Math.floor(min / 60) * 60, max: Math.min(1440, Math.ceil(max / 60) * 60), plage };
}

const prvPeindreSi = (zone, html) => { if (zone && zone.__rendu !== html) { zone.__rendu = html; zone.innerHTML = html; } };

function privatiserPeindre() {
  if (!prv) return;
  const b = privatiserBornes();
  const largeur = Math.max(60, b.max - b.min);
  const pc = (m) => `${(((m - b.min) / largeur) * 100).toFixed(3)}%`;
  const large = (d, f) => `${(((f - d) / largeur) * 100).toFixed(3)}%`;
  const valide = b.debut !== null && b.fin !== null && b.fin > b.debut;
  const sel = document.getElementById('prvJaugeSel');
  if (sel) {
    sel.hidden = !valide;
    if (valide) { sel.style.left = pc(b.debut); sel.style.width = large(b.debut, b.fin); }
  }
  const marques = [];
  const pas = largeur > 600 ? 120 : 60;
  for (let m = b.min; m <= b.max; m += pas) marques.push(`<span style="left:${pc(m)}">${m >= 1440 ? 'minuit' : `${Math.floor(m / 60)} h`}</span>`);
  prvPeindreSi(document.getElementById('prvJaugeHeures'), marques.join(''));
  // Les reservations du jour, sur des lignes (un trait par visite, jamais l un sous l autre).
  const touchees = new Set(((prv.vu && prv.vu.reservations) || []).map(r => Number(r.id)));
  const resas = (prv.journee.resas || []).map(r => ({ r, d: prvMinutes(r.debut), f: r.fin === 'minuit' ? 1440 : prvMinutes(r.fin) })).filter(x => x.d !== null && x.f !== null && x.f > x.d).sort((x, y) => x.d - y.d);
  const fins = [];
  const traits = resas.map(x => {
    let ligne = fins.findIndex(f => f <= x.d);
    if (ligne < 0) { ligne = fins.length; fins.push(0); }
    fins[ligne] = x.f;
    return { ...x, ligne };
  });
  const lignes = Math.max(1, Math.min(6, fins.length));
  document.getElementById('prvPiste')?.style.setProperty('--prv-lignes', String(lignes));
  prvPeindreSi(document.getElementById('prvJaugeResas'), traits.filter(t => t.ligne < 6).map(t => `<span class="prv-trait${touchees.has(Number(t.r.id)) ? ' is-touchee' : ''}" style="left:${pc(Math.max(b.min, t.d))};width:${large(Math.max(b.min, t.d), Math.min(b.max, t.f))};top:calc(${t.ligne} * var(--prv-ligne))"></span>`).join(''));
  prvPeindreSi(document.getElementById('prvJaugePrivees'), privatiserAutresDuJour(b.corps.date).map(p => {
    const d = Math.max(b.min, p.debut ?? 0);
    const f = Math.min(b.max, p.fin == null ? 1440 : p.fin);
    return f > d ? `<span class="prv-autre-prive" style="left:${pc(d)};width:${large(d, f)}"></span>` : '';
  }).join(''));
  const ferme = document.getElementById('prvFerme');
  if (ferme) ferme.hidden = !b.plage.ferme;
  const duree = document.getElementById('prvDuree');
  if (duree) duree.textContent = valide ? prvDuree(b.fin - b.debut) : '';
  privatiserRaccourcis(b);
  privatiserResume(b, valide);
}

// Les autres privatisations du jour (celle qui se modifie n en fait pas partie).
function privatiserAutresDuJour(date) {
  if (!date || !prv) return [];
  const remplace = new Set(prv.remplace);
  const blocs = [...(date === state.currentDate ? (fermeturesServies(date) || []) : []), ...(availabilityBlocksCache.blocks || [])]
    .filter(b => b && b.kind === 'private' && (b.date || date) === date && !remplace.has(Number(b.id)));
  const vus = privatisationsGroupees(blocs, date);
  const cles = new Set(vus.flatMap(p => p.ids));
  const deLaListe = (privatisationsAVenir || []).filter(x => x.date === date && !(x.ids || []).some(id => remplace.has(Number(id)) || cles.has(Number(id)))).map(privatisationDeLaListe);
  return [...vus, ...deLaListe];
}

// Les plages d un toucher, seulement celles que le jour ouvre.
function privatiserRaccourcis(b) {
  const { open, close } = b.plage;
  const choix = [['Toute la journée', open, close]];
  if (open < 12 * 60 && close > 12 * 60) choix.push(['Le matin', open, 12 * 60]);
  if (open < 18 * 60 && close > 13 * 60) choix.push(['L’après-midi', Math.max(open, 13 * 60), Math.min(close, 18 * 60)]);
  if (close > 18 * 60) choix.push(['Le soir', Math.max(open, 18 * 60), close]);
  prvPeindreSi(document.getElementById('prvRaccourcis'), choix.filter(([, d, f]) => f > d).map(([mot, d, f]) => {
    const on = b.debut === d && b.fin === f;
    return `<button type="button" class="prv-raccourci${on ? ' is-on' : ''}" aria-pressed="${on}" onclick="privatiserPlage(${Number(d)}, ${Number(f)})">${escapeHtml(mot)}<small>${escapeHtml(`${prvHeureDite(d)} à ${prvHeureDite(f)}`)}</small></button>`;
  }).join(''));
}

function privatiserPlage(debut, fin) {
  const de = document.getElementById('prvDe');
  const a = document.getElementById('prvA');
  if (!de || !a) return;
  de.value = prvHeure(debut);
  a.value = prvHeure(fin);
  privatiserChange();
}

// Ce que ca donne, en clair, a droite : le jour, la plage, ce qui ferme, pour qui, et la phrase que
// le planning dira (le format de lib/availability-blocks.js phraseDuBlocage).
function privatiserResume(b, valide) {
  const corps = b.corps;
  const centre = getCurrentStaffCenterId();
  const jour = corps.date ? rsJourMot(corps.date) : 'Choisissez le jour';
  const longue = corps.date ? prvDateLongue(corps.date) : '';
  const ids = corps.toutLeCentre ? privatiserActivites().map(a => a.id) : corps.activites;
  const photos = ids.slice(0, 5).map(id => ficheVisuelActivite({ centerId: centre }, { activityId: id, nom: rvNomActivite(id) })).join('');
  const quoi = corps.toutLeCentre ? 'Tout le centre' : (corps.activites.length ? corps.activites.map(id => rvNomActivite(id)).join(', ') : 'Aucune activité choisie');
  const phrase = valide
    ? `${privatisationPhrase({ nom: corps.nom, debut: b.debut, fin: b.fin })}${corps.toutLeCentre || !corps.activites.length ? '' : ` (${corps.activites.map(id => rvNomActivite(id)).join(', ')})`}.`
    : '';
  prvPeindreSi(document.getElementById('prvResume'), `<p class="prv-resume__jour">${escapeHtml(jour)}${longue && longue.toLowerCase() !== jour.toLowerCase() ? `<span>${escapeHtml(longue)}</span>` : ''}</p>
    <p class="prv-resume__heures">${valide ? `<b>${escapeHtml(prvHeureDite(b.debut))}</b><i aria-hidden="true"></i><b>${escapeHtml(prvHeureDite(b.fin))}</b><span>${escapeHtml(prvDuree(b.fin - b.debut))}</span>` : '<span>Choisissez les heures</span>'}</p>
    <p class="prv-resume__quoi">${photos ? `<span class="prv-resume__photos">${photos}</span>` : ''}<span>${escapeHtml(quoi)}</span></p>
    <p class="prv-resume__nom${corps.nom ? '' : ' is-vide'}">${escapeHtml(corps.nom || 'Le nom du groupe')}</p>
    ${phrase ? `<p class="prv-resume__planning"><small>Sur le planning</small><span class="prv-phrase">${escapeHtml(phrase)}</span></p>` : ''}`);
}

// La plage se tire a la souris ou au doigt : une poignee deplace son bord, la plage entiere glisse,
// un toucher ailleurs sur la jauge y amene le bord le plus proche. Au quart d heure.
function privatiserTirer(event) {
  if (!prv || (event.button !== undefined && event.button !== 0)) return;
  const piste = document.getElementById('prvPiste');
  if (!piste) return;
  const b = privatiserBornes();
  if (b.debut === null || b.fin === null || !(b.fin > b.debut)) return;
  const boite = piste.getBoundingClientRect();
  const largeur = Math.max(60, b.max - b.min);
  const aMinute = (x) => b.min + ((x - boite.left) / Math.max(1, boite.width)) * largeur;
  const quart = (m) => Math.round(m / PRV_PAS) * PRV_PAS;
  let quoi = ((event.target.closest && event.target.closest('[data-prv-tirer]')) || { dataset: {} }).dataset.prvTirer || '';
  const depart = aMinute(event.clientX);
  if (!quoi) quoi = Math.abs(depart - b.debut) <= Math.abs(depart - b.fin) ? 'debut' : 'fin';
  const origine = { debut: b.debut, fin: b.fin };
  const appliquer = (x) => {
    const m = aMinute(x);
    let debut = origine.debut;
    let fin = origine.fin;
    if (quoi === 'debut') debut = Math.min(quart(m), fin - PRV_PAS);
    else if (quoi === 'fin') fin = Math.max(quart(m), debut + PRV_PAS);
    else {
      const long = origine.fin - origine.debut;
      debut = Math.max(b.min, Math.min(b.max - long, origine.debut + quart(m - depart)));
      fin = debut + long;
    }
    debut = Math.max(b.min, debut);
    fin = Math.min(b.max, fin);
    const de = document.getElementById('prvDe');
    const a = document.getElementById('prvA');
    if (de) de.value = prvHeure(debut);
    if (a) a.value = prvHeure(fin);
    privatiserPeindre();
  };
  event.preventDefault();
  try { piste.setPointerCapture(event.pointerId); } catch (error) { /* (souris deja relachee) */ }
  piste.classList.add('is-tire');
  if (quoi !== 'tout') appliquer(event.clientX);
  const bouge = (e) => appliquer(e.clientX);
  const lacher = () => {
    piste.removeEventListener('pointermove', bouge);
    piste.removeEventListener('pointerup', lacher);
    piste.removeEventListener('pointercancel', lacher);
    piste.classList.remove('is-tire');
    privatiserChange();
  };
  piste.addEventListener('pointermove', bouge);
  piste.addEventListener('pointerup', lacher);
  piste.addEventListener('pointercancel', lacher);
}

// Les reservations de la journee, pour la jauge : la lecture a blanc de la journee entiere (le
// serveur les dit avec leurs heures). Un autre groupe deja prive ce jour-la refuse cette lecture : la
// jauge reste sans traits, la liste de droite, elle, dit tout.
async function privatiserJournee(date) {
  if (!prv || !date) return;
  const plage = privatiserOuverture(date);
  const ticket = ++prv.ticketJour;
  prv.journee = { date, plage, resas: [] };
  try {
    const reponse = await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'privatiser', centerId: getCurrentStaffCenterId(), aBlanc: true, date, startTime: availabilityMinutesToHHMM(plage.open), endTime: plage.close >= 1440 ? '24:00' : availabilityMinutesToHHMM(plage.close), toutLeCentre: true, nom: 'Journée', ...(prv.remplace.length ? { remplace: prv.remplace } : {}) }) });
    if (!prv || ticket !== prv.ticketJour) return;
    prv.journee.resas = Array.isArray(reponse && reponse.reservations) ? reponse.reservations : [];
  } catch (error) {
    // (la jauge reste sans les reservations du jour)
  }
  if (prv && ticket === prv.ticketJour) privatiserPeindre();
}

// LA LISTE, LUE EN DIRECT : la demande telle qu elle est, a blanc. Le dernier ticket gagne : la
// reponse d une demande deja changee ne s affiche jamais.
async function privatiserVerifier() {
  if (!prv) return;
  const corps = privatiserLire();
  const zone = document.getElementById('prvVu');
  const manque = privatiserManque(corps, { pourVoir: true });
  if (manque) {
    prv.vu = null;
    if (zone) zone.classList.remove('is-lecture');
    prvPeindreSi(zone, `<p class="prv-attente">${escapeHtml(manque)}</p>`);
    privatiserBouton();
    return;
  }
  const ticket = ++prv.ticket;
  if (zone) zone.classList.add('is-lecture');
  try {
    const reponse = await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify({ action: 'privatiser', centerId: getCurrentStaffCenterId(), ...corps, nom: corps.nom || 'Groupe privé', ...(prv.remplace.length ? { remplace: prv.remplace } : {}), aBlanc: true }) });
    if (prv && ticket === prv.ticket) {
      privatiserErreur('');
      privatiserMontrer(reponse);
    }
  } catch (error) {
    if (!prv || ticket !== prv.ticket) return;
    prv.vu = null;
    prvPeindreSi(zone, '');
    privatiserErreur(error?.message || 'Lecture impossible pour le moment. Réessayez.');
  } finally {
    if (prv && ticket === prv.ticket && zone) zone.classList.remove('is-lecture');
    privatiserBouton();
  }
}

function privatiserMontrer(reponse, { garderLeChoix = false } = {}) {
  const zone = document.getElementById('prvVu');
  if (!zone || !prv) return;
  const coche = document.querySelector('input[name="prvGroupe"]:checked');
  const voulu = garderLeChoix || coche ? ((coche && coche.value) || '') : (prv.reservationId ? String(prv.reservationId) : '');
  const reservations = Array.isArray(reponse && reponse.reservations) ? reponse.reservations : [];
  const choisi = reservations.some(r => String(r.id) === voulu) ? voulu : '';
  prv.vu = { cle: privatiserCle(privatiserLire()), reservations };
  const detail = (r) => [`${r.debut} à ${r.fin}`, r.libelle, r.joueurs ? `${r.joueurs} joueur${r.joueurs > 1 ? 's' : ''}` : ''].filter(Boolean).join(', ');
  const html = reservations.length
    ? `<p class="prv-dit">${reservations.length > 1 ? `${reservations.length} réservations sont déjà sur ces heures. Elles restent à leur place. Si l’une d’elles est le groupe privé, touchez-la.` : 'Une réservation est déjà sur ces heures. Elle reste à sa place. Si c’est le groupe privé, touchez-la.'}</p>
      <ul class="prv-resas">${reservations.map(r => `<li><label class="prv-resa"><input type="radio" name="prvGroupe" value="${Number(r.id)}"${String(r.id) === choisi ? ' checked' : ''}><span class="prv-resa__h">${escapeHtml(r.debut)}</span><span class="prv-resa__t"><b>${escapeHtml(r.nom)}</b><small>${escapeHtml(detail(r))}</small></span></label></li>`).join('')}
      <li><label class="prv-resa is-aucune"><input type="radio" name="prvGroupe" value=""${choisi ? '' : ' checked'}><span class="prv-resa__t">Aucune n’est le groupe privé</span></label></li></ul>`
    : '<p class="prv-dit is-libre">Aucune réservation sur ces heures.</p>';
  zone.__rendu = html;
  zone.innerHTML = html;
  privatiserPeindre();
}

// « Privatiser » s allume quand la liste lue est celle de la demande, et qu elle a un nom.
function privatiserBouton() {
  const bouton = document.getElementById('prvOk');
  if (!bouton || !prv) return;
  const corps = privatiserLire();
  bouton.disabled = Boolean(privatiserManque(corps)) || !prv.vu || prv.vu.cle !== privatiserCle(corps);
}

async function privatiserEnvoyer(event) {
  if (event) event.preventDefault();
  if (!prv) return;
  const corps = privatiserLire();
  const manque = privatiserManque(corps);
  if (manque) { privatiserErreur(manque); return; }
  if (!prv.vu || prv.vu.cle !== privatiserCle(corps)) {
    privatiserErreur('Un instant : la liste des réservations se relit.');
    privatiserVerifier();
    return;
  }
  const bouton = document.getElementById('prvOk');
  if (bouton) bouton.disabled = true;
  const remplace = prv.remplace.slice();
  const retour = prv.depuisLaListe;
  const envoi = { action: 'privatiser', centerId: getCurrentStaffCenterId(), ...corps, reservationsVues: prv.vu.reservations.map(r => Number(r.id)) };
  if (remplace.length) envoi.remplace = remplace;
  const groupe = document.querySelector('input[name="prvGroupe"]:checked');
  if (groupe && groupe.value) envoi.reservationId = Number(groupe.value);
  try {
    const reponse = await apiRequest(API_ENDPOINTS.ops, { method: 'POST', body: JSON.stringify(envoi) });
    smFenetreFermer();
    toast(remplace.length ? 'Privatisation modifiée.' : ((reponse.privatisation && reponse.privatisation.phrase) || 'Privatisation enregistrée.'));
    await privatisationRelire(corps.date);
    if (retour) ouvrirListePrivatisations();
  } catch (error) {
    const payload = error && error.payload;
    // Une reservation arrivee pendant la lecture : la liste revient a jour, a relire avant d enregistrer.
    if (payload && payload.code === 'reservations_sur_la_plage' && Array.isArray(payload.reservations)) privatiserMontrer(payload, { garderLeChoix: true });
    privatiserErreur(error?.message || 'Privatisation impossible pour le moment. Réessayez.');
  } finally {
    privatiserBouton();
  }
}

// ── LES PRIVATISATIONS A VENIR (2026-11-20) : une fenetre, les jours dans l ordre, une ligne par
// privatisation ; « Modifier » rouvre la fenetre remplie, « Retirer » demande confirmation. ──────
function ouvrirListePrivatisations() {
  if (!peutGeste('privatiser')) { toast('Votre rôle ne permet pas de voir les privatisations. Demandez à un responsable.'); return; }
  smFenetreOuvrir({
    titre: 'Privatisations à venir',
    sous: 'Les plages fermées pour un groupe, de la plus proche à la plus lointaine.',
    classe: 'prv-liste-fen',
    corps: '<div class="prv-liste" id="prvListe" aria-live="polite"><p class="prv-attente">Lecture…</p></div><div class="bdg-actions prv-liste-pied"><button type="button" class="bdg-p" onclick="smFenetreFermer(); ouvrirPrivatiser()">Privatiser…</button></div>',
  });
  chargerListePrivatisations();
}

async function chargerListePrivatisations() {
  const zone = document.getElementById('prvListe');
  if (!zone) return;
  let liste = [];
  try {
    liste = await lirePrivatisationsAVenir();
  } catch (error) {
    if (document.getElementById('prvListe')) zone.innerHTML = `<p class="bdg-hf-err">${escapeHtml(error?.message || 'Lecture impossible pour le moment. Réessayez.')}</p>`;
    return;
  }
  if (!document.getElementById('prvListe')) return;
  if (!liste.length) { zone.innerHTML = '<p class="prv-attente">Aucune privatisation à venir.</p>'; return; }
  const parJour = new Map();
  liste.forEach(x => { if (!parJour.has(x.date)) parJour.set(x.date, []); parJour.get(x.date).push(x); });
  zone.innerHTML = [...parJour.entries()].map(([date, duJour]) => {
    const mot = rsJourMot(date);
    const longue = prvDateLongue(date);
    return `<section class="prv-liste__jour"><h4>${escapeHtml(mot)}${longue.toLowerCase() !== mot.toLowerCase() ? `<span>${escapeHtml(longue)}</span>` : ''}</h4>${duJour.map(x => {
      const p = privatisationDeLaListe(x);
      const ids = escapeJsString(p.ids.join(','));
      return `<div class="prv-liste__l" data-privatisation="${escapeHtml(p.ids.join(','))}"><span class="prv-liste__h"><b>${escapeHtml(prvHeureDite(p.debut))}</b><i aria-hidden="true"></i><b>${escapeHtml(prvHeureDite(p.fin))}</b></span><span class="prv-liste__t"><b>${escapeHtml(p.nom || 'Groupe privé')}</b><small>${escapeHtml(privatisationPortee(p))}</small></span><span class="pb-prive__gestes"><button type="button" class="pb-prive__b" onclick="modifierPrivatisationUi('${ids}', { depuisLaListe: true })">Modifier</button><button type="button" class="pb-prive__x" onclick="retirerPrivatisationUi('${ids}')">Retirer</button></span></div>`;
    }).join('')}</section>`;
  }).join('');
}

// LES PARAMETRES DU POSTE (2026-09-25). La page etait une maquette : trois
// blocs sans style (« InterfaceThème Clair » colle, boutons bruts du
// navigateur) et un bloc « Ops » qui chargeait de la plomberie interne. Restent
// les trois reglages qu un gerant utilise vraiment, chacun dit ce qu il fait.
function renderStaffUtilitySettings() {
  const light = state.staffTheme === 'light';
  const count = getStaffUtilityReservations().length;
  const day = parseLocalDate(state.currentDate).toLocaleDateString('fr-BE', { weekday: 'long', day: 'numeric', month: 'long' });
  return `<div class="settings-list">
    <div class="settings-row">
      <div class="settings-copy">
        <h2>Apparence</h2>
        <p>Le thème de la console sur ce poste. Les autres postes gardent le leur.</p>
      </div>
      <div class="settings-seg" role="group" aria-label="Thème de la console">
        <button type="button" aria-pressed="${light ? 'true' : 'false'}" class="${light ? 'is-on' : ''}" onclick="setStaffTheme('light')">Clair</button>
        <button type="button" aria-pressed="${light ? 'false' : 'true'}" class="${light ? '' : 'is-on'}" onclick="setStaffTheme('dark')">Sombre</button>
      </div>
    </div>
    ${peutGeste('exporter') ? `<div class="settings-row">
      <div class="settings-copy">
        <h2>Export du planning</h2>
        <p>${escapeHtml(formatStaffTerrainCount(count, 'réservation'))} le ${escapeHtml(day)}, dans un fichier tableur (CSV) : heure, client, téléphone, offre, joueurs, pistes, statut et montant.</p>
      </div>
      <button type="button" class="utility-action" onclick="exportStaffPlanningCsv('day')"${count ? '' : ' disabled'}>Exporter en CSV</button>
    </div>` : ''}
    <div class="settings-row">
      <div class="settings-copy">
        <h2>Données</h2>
        <p>La console se synchronise toute seule toutes les quelques secondes. Ce bouton force un rechargement immédiat depuis le serveur.</p>
      </div>
      <button type="button" class="utility-action" onclick="refreshStaffPlanning()">Actualiser</button>
    </div>
  </div>`;
}

function getStaffUtilityPageModel(page = getStaffMenuPage()) {
  const reservations = getStaffUtilityReservations();
  // Pas de bouton secondaire par defaut : « Voir planning » s affichait sur
  // chaque page, doublon de la barre laterale, et ouvrait meme les
  // Reservations depuis Formules. Une page qui a une vraie deuxieme action
  // la declare.
  const base = {
    page,
    layout: 'default',
    eyebrow: 'Journée',
    title: 'Espace staff',
    subtitle: getStaffUtilitySyncLabel(),
    primaryLabel: 'Réservation',
    primaryAction: "openQuickBook({ date: state.currentDate, type: 'bowling' })",
    secondaryLabel: '',
    secondaryAction: '',
    kpis: [],
    body: ''
  };
  if (page === 'formules') {
    const formuleRows = reservations.filter(reservation => reservation.type === 'formule' || reservation.formuleId || formuleDuComptoir(reservation));
    const totals = formuleRows.filter(reservationHasFormulaActivities).reduce((acc, reservation) => {
      const summary = getFormulaActivityProgressSummary(reservation);
      acc.done += summary.done;
      acc.total += summary.total;
      return acc;
    }, { done: 0, total: 0 });
    const players = formuleRows.reduce((sum, reservation) => sum + Number(reservation.pax || 0), 0);
    // Le sous-titre dit la journee en une ligne. Il ne dit plus a quoi sert la
    // page (« Cochez chaque activité au fur et à mesure... ») : les cases le
    // disent d elles-memes. « 0/8 activités faite » : le pluriel suivait le
    // nombre de coches, pas le nombre d activites qu il qualifie ; les deux
    // accords s indexent sur le meme mot. Le compte n est plus ecrit deux fois
    // (en-tete de panneau et tete de groupe) : chaque groupe dit le sien.
    const summary = formuleRows.length ? [
      formatStaffTerrainCount(formuleRows.length, 'formule'),
      formatStaffTerrainCount(players, 'joueur'),
      totals.total ? `${totals.done}/${totals.total} activité${totals.total > 1 ? 's' : ''} cochée${totals.total > 1 ? 's' : ''}` : ''
    ].filter(Boolean).join(' · ') : '';
    return {
      ...base,
      layout: 'events',
      eyebrow: 'Journée',
      // Le titre est celui de la barre laterale : une entree « Formules » qui
      // ouvre « Formules, suivi des activités » faisait croire a une autre page.
      title: 'Formules',
      subtitle: [getStaffUtilitySyncLabel(), summary].filter(Boolean).join(' · '),
      hidePanelHead: true,
      primaryLabel: 'Nouvelle formule',
      primaryAction: "openQuickBook({ date: state.currentDate, type: 'formule' })",
      body: renderStaffFormulesBoard(formuleRows)
    };
  }
  // Arrivees, En cours et Evenements ne font plus qu une page (voir
  // getStaffTerrainBoard) ; les anciennes adresses y menent par
  // STAFF_PAGE_ALIASES.
  if (page === 'arrivals') {
    const board = getStaffTerrainBoard(reservations);
    const players = reservations.reduce((sum, reservation) => sum + Number(reservation.pax || 0), 0);
    const doneCount = board.done.length;
    const summary = reservations.length ? [
      formatStaffTerrainCount(reservations.length, 'réservation'),
      formatStaffTerrainCount(players, 'joueur'),
      doneCount ? `${doneCount} terminée${doneCount > 1 ? 's' : ''} et payée${doneCount > 1 ? 's' : ''}` : ''
    ].filter(Boolean).join(' · ') : '';
    return {
      ...base,
      layout: 'terrain',
      eyebrow: 'Journée',
      title: 'Terrain',
      subtitle: [getStaffUtilitySyncLabel(), summary].filter(Boolean).join(' · '),
      hidePanelHead: true,
      body: renderStaffTerrainBoard(board)
    };
  }
  // Plus de branche « groups » : la page a disparu le 2026-07-13 (fusion
  // Clients+Groupes), tous ses chemins d'accès sont aliasés vers Clients /
  // segment « À venir » (openStaffMenuPage, renderStaffData, renderStaffUtilityPage).
  if (page === 'requests') {
    // LA PAGE DES DEMANDES SUR MESURE porte son en-tete en tete de sa liste : le titre et le retard ;
    // les onglets disent le reste.
    return {
      ...base,
      layout: 'requests',
      eyebrow: 'Clients & marketing',
      title: 'Demandes sur mesure',
      subtitle: '',
      hideHero: true,
      hidePanelHead: true,
      hideDateAction: true,
      primaryLabel: '',
      primaryAction: '',
      secondaryLabel: '',
      secondaryAction: '',
      body: renderStaffRequestsBoard()
    };
  }
  if (page === 'contacts') {
    const clientRows = getStaffClientRows();
    const missing = clientRows.filter(row => !row.email || !row.phone).length;
    return {
      ...base,
      layout: 'contacts',
      eyebrow: 'Clients & marketing',
      title: 'Contacts',
      subtitle: 'Carnet client issu des réservations réelles.',
      primaryLabel: 'Exporter CSV',
      primaryAction: peutGeste('exporter') ? 'exportStaffClientsCsv()' : '',
      kpis: [
        ['Contacts', clientRows.length, 'profils consolidés'],
        ['Téléphone', clientRows.filter(row => row.phone).length, 'renseignés'],
        ['Email', clientRows.filter(row => row.email).length, 'renseignés'],
        ['À compléter', missing, 'fiche incomplète']
      ],
      body: renderStaffUtilityContactLedger(clientRows)
    };
  }
  if (page === 'lanes') {
    // La fenetre 30 j vit dans le cache CRM : on le remplit des l arrivee
    // sur la page (le rechargement repeint via loadStaffClientData).
    if (typeof ensureStaffClientData === 'function') ensureStaffClientData();
    ensureStaffCenterConfigForPlanning();
    const laneBoard = buildStaffLaneBoardModel();
    return {
      ...base,
      layout: 'lanes',
      eyebrow: 'Activités & tarifs',
      title: 'Pistes bowling',
      subtitle: 'Fermer, replacer, vendre un creux : l’état vivant de chaque piste.',
      primaryLabel: 'Réserver une piste',
      primaryAction: peutGeste('reserver') ? "openQuickBook({ date: state.currentDate, type: 'bowling' })" : '',
      kpis: laneBoard.kpis,
      body: renderStaffLaneBoard(laneBoard)
    };
  }
  if (page === 'laserGame') {
    if (typeof ensureStaffClientData === 'function') ensureStaffClientData();
    const laserBoard = buildStaffLaserBoardModel();
    return {
      ...base,
      layout: 'laser',
      eyebrow: 'Activités & tarifs',
      title: 'Laser Game',
      subtitle: 'Prochain lancement, sessions à compléter, bilan 30 jours.',
      primaryLabel: 'Réserver un laser',
      primaryAction: peutGeste('reserver') ? "openQuickBook({ date: state.currentDate, type: 'laser' })" : '',
      kpis: laserBoard.kpis,
      body: renderStaffLaserBoard(laserBoard)
    };
  }
  if (page === 'secours') {
    return {
      ...base,
      layout: 'secours',
      eyebrow: 'Administration',
      title: 'Secours',
      subtitle: 'Ce qui permet d’accueillir les groupes si Pinlane ne répond plus.',
      hidePanelHead: true,
      hideDateAction: true,
      primaryAction: '',
      secondaryAction: '',
      body: renderStaffUtilitySecours()
    };
  }
  if (page === 'establishment') {
    return {
      ...base,
      layout: 'establishment',
      eyebrow: 'Administration',
      title: 'Établissement',
      subtitle: '',
      // La page porte son propre en-tete : le nom du centre et ce qu il fait aujourd hui.
      hideHero: true,
      hidePanelHead: true,
      hideDateAction: true,
      primaryAction: '',
      body: renderStaffUtilityEstablishment()
    };
  }
  if (page === 'users') {
    // Plus de tuiles chiffrees en tete (« Permissions du role 19/29 » ne
    // disait rien a personne) : la page commence par qui entre, en phrases.
    return {
      ...base,
      layout: 'users',
      eyebrow: 'Administration',
      title: 'Équipe & accès',
      subtitle: 'Qui entre dans la console, avec quel code, dans quels centres, et ce que chacun y voit.',
      hidePanelHead: true,
      hideDateAction: true,
      primaryLabel: 'Ajouter une personne',
      primaryAction: 'createStaffMember()',
      secondaryLabel: 'Créer un rôle',
      secondaryAction: 'createStaffCustomRole()',
      kpis: [],
      body: renderStaffUtilityUsers()
    };
  }
  if (page === 'settings') {
    return {
      ...base,
      layout: 'settings',
      eyebrow: 'Compte',
      title: 'Paramètres',
      subtitle: 'Les réglages de ce poste.',
      hidePanelHead: true,
      hideDateAction: true,
      primaryLabel: '',
      primaryAction: '',
      body: renderStaffUtilitySettings()
    };
  }
  return base;
}

// Des changements non enregistres sur la fiche : ni le direct ni un repeint n y touchent, son rendu repart de la config du serveur et les effacerait.
function ficheEtablissementEnCours() { return Boolean(state.establishmentEditing); }

function renderStaffUtilityPage() {
  const root = document.getElementById('staffUtilityPage');
  if (!root) return;
  if (state.staffMenuPage === 'establishment' && ficheEtablissementEnCours() && root.querySelector('[data-estab-page]')) return;
  const model = getStaffUtilityPageModel();
  // La date n est plus recopiee sous le titre : le selecteur de date, a cote,
  // l affiche deja avec le jour de la semaine.
  const heroSubtitle = escapeHtml(model.subtitle || '');
  const overviewPages = new Set(['users']);
  const archivePages = new Set(['groups', 'contacts']);
  // L en-tete du panneau RECOPIAIT le titre de la page (« Pistes » sous
  // « Pistes ») et portait un « Rafraîchir » qui ne faisait que redessiner
  // les memes donnees : les deux partent. Reste une ligne, seulement si elle
  // dit quelque chose (compte propre a la page, ou connexion perdue).
  const panelSubtitle = model.panelSubtitle || getStaffUtilitySyncLabel();
  const panelHead = model.hidePanelHead || !panelSubtitle ? '' : `<p class="utility-panel-note">${escapeHtml(panelSubtitle)}</p>`;
  // Entree de page : une fois par navigation, jamais au poll ni au tic de la
  // minute (meme repere de visite que l accueil et les pages pv2).
  const pages = window.PinlaneV2;
  const active = isStaffUtilityActive();
  const arriving = active && (pages ? pages.lastPage !== model.page : !root.firstElementChild);
  if (pages && active) pages.lastPage = model.page;
  root.className = `staff-utility-page utility-page-${escapeHtml(model.page)} utility-layout-${escapeHtml(model.layout || 'default')}${arriving && !prefersReducedMotion() ? ' utility-enter' : ''}`;
  // CE QU ON ETAIT EN TRAIN DE FAIRE SURVIT AU REPAINT (2026-08-20). La page se
  // repeint entierement des qu une reponse reseau arrive (file des demandes,
  // fil de mails, changement de statut). Sans cette sauvegarde, le champ en
  // cours de saisie est recree : le curseur saute a la fin, ou pire, le focus
  // part et la frappe suivante se perd. Meme chose pour le defilement d une
  // liste laterale, qui remontait en haut toute seule.
  const focused = document.activeElement;
  const focusedId = focused && root.contains(focused) && focused.id ? focused.id : '';
  const caretStart = focused && typeof focused.selectionStart === 'number' ? focused.selectionStart : null;
  const caretEnd = focused && typeof focused.selectionEnd === 'number' ? focused.selectionEnd : null;
  const keptScroll = [];
  root.querySelectorAll('[data-keep-scroll]').forEach((node) => {
    if (node.id && node.scrollTop) keptScroll.push([node.id, node.scrollTop]);
  });
  const hero = model.hideHero ? '' : `
    <section class="utility-hero">
      <div>
        <span>${escapeHtml(model.eyebrow)}</span>
        <h1>${escapeHtml(model.title)}</h1>
        ${heroSubtitle ? `<p>${heroSubtitle}</p>` : ''}
      </div>
      <div class="utility-actions">
        ${model.hideDateAction ? '' : staffDateNavHtml()}
        ${model.secondaryAction ? `<button type="button" onclick="${model.secondaryAction}">${escapeHtml(model.secondaryLabel)}</button>` : ''}
        ${model.primaryAction ? `<button type="button" class="primary" onclick="${model.primaryAction}">${escapeHtml(model.primaryLabel)}</button>` : ''}
      </div>
    </section>`;
  root.innerHTML = `${hero}
    ${overviewPages.has(model.page) ? renderStaffUtilityOverview(model) : ''}
    <section class="utility-panel ${model.hidePanelHead ? 'utility-panel-flat' : ''}">
      ${panelHead}
      ${model.body}
    </section>
  `;
  keptScroll.forEach(([id, top]) => {
    const node = document.getElementById(id);
    if (node) node.scrollTop = top;
  });
  if (focusedId) {
    const again = document.getElementById(focusedId);
    if (again && again !== document.activeElement) {
      again.focus({ preventScroll: true });
      if (caretStart !== null && typeof again.setSelectionRange === 'function') {
        try { again.setSelectionRange(caretStart, caretEnd); } catch (error) {}
      }
    }
  }
  if (archivePages.has(model.page)) ensureStaffClientData();
  if (model.page === 'groups' || model.page === 'requests') ensureStaffCustomRequests();
  // Le fil de la demande ouverte se charge tout seul : l'historique existait
  // deja, il fallait cliquer un bouton par carte pour le voir.
  if (model.page === 'requests') ensureStaffRequestThread();
  // La demande ouverte : son client se lit, Pinlane prepare la reponse si rien ne l est, et le bureau
  // prend la hauteur de l ecran.
  if (model.page === 'requests') { ensureStaffRequestPinlane(); bdgAjusterHauteur(); }
  if ((model.page === 'emails' || model.page === 'establishment') && !opsAdminCache.loaded && !opsAdminCache.loading) requestOpsAdminLoad(false);
}

function isStaffClientsActive() {
  return state.view === 'staff' && getStaffMenuPage() === 'clients';
}

function getPricingTypeLabel(type) {
  return type === 'bowling' ? 'Bowling'
    : type === 'laser' ? 'Laser Game'
    : type === 'special' ? 'Formule spéciale'
    : 'Formule';
}

function getPricingPriceLabel(row) {
  if (row.type === 'bowling') return `${formatMontant(row.price)} / piste`;
  if (row.type === 'laser') return `${formatMontant(row.price)} / personne`;
  return `${formatMontant(row.price)} ${row.priceType === 'per_lane' ? '/ piste' : '/ personne'}`;
}

function getPricingAsset(type) {
  if (type === 'bowling') return './assets/pricing/bowling.png';
  if (type === 'laser') return './assets/pricing/laser.png';
  if (type === 'special') return './assets/pricing/special.png';
  return './assets/pricing/formula.png';
}

function getPricingTone(type) {
  if (type === 'bowling') return 'green';
  if (type === 'laser') return 'blue';
  if (type === 'special') return 'violet';
  return 'amber';
}

// LES CHIFFRES DE LA PAGE TARIFS PORTENT SUR 30 JOURS. Ils comptaient
// « les données locales » : ce que la console avait charge, une fenetre que
// personne ne connait (le jour affiche et ses voisins). Meme fenetre que
// Pistes et Laser Game : les 30 jours revolus, annulations exclues.
// L historique vient de /api/admin-range : sans le droit de le lire, la page
// ne compte RIEN (jamais les seules reservations en memoire).
function canReadStaffReservationHistory() {
  return typeof canUseStaffPermission !== 'function'
    || ['direction.view', 'reservations.view', 'clients.view'].some(permission => canUseStaffPermission(permission));
}
if (typeof window !== 'undefined') window.canReadStaffReservationHistory = canReadStaffReservationHistory;

function getPricingReservations() {
  if (!canReadStaffReservationHistory()) return [];
  return getStaffResourceHistoryRows();
}

function getPricingUsageMap() {
  const usage = new Map();
  const register = (id, reservation) => {
    const item = usage.get(id) || { count: 0, players: 0, revenue: 0 };
    item.count += 1;
    item.players += Number(reservation.pax || 0);
    item.revenue += Number(reservation.price || 0);
    usage.set(id, item);
  };
  getPricingReservations().forEach(reservation => {
    if (reservation.formuleId) {
      register(`formula-${reservation.formuleId}`, reservation);
      return;
    }
    if (reservation.type === 'laser') {
      const option = LASER_GAME_OPTIONS.find(item => Number(item.value) === Number(reservation.duration || 0.5)) || LASER_GAME_OPTIONS[0];
      register(`laser-${option.games}`, reservation);
      return;
    }
    if (reservation.type === 'bowling') {
      register(`bowling-${Number(reservation.duration || 1)}`, reservation);
    }
  });
  return usage;
}

// LA SOURCE des formules pour les ecrans de la console (grille Tarifs,
// Etablissement > Offres) : la liste VIVE du catalogue (customs comprises,
// editions refletees, nom/prix effectifs du centre) quand elle est chargee,
// la constante FORMULES sinon. Les formules retirees du catalogue sont
// EXCLUES par defaut (elles n'existent plus pour le centre) ; la grille
// Tarifs les demande pour les montrer barrees et restaurables.
function getConsoleFormuleCatalog({ includeRemoved = false } = {}) {
  const live = typeof window !== 'undefined' && typeof window.pevLiveFormules === 'function'
    ? window.pevLiveFormules()
    : null;
  if (!Array.isArray(live) || !live.length) return getEffectiveCatalogFormules();
  return includeRemoved ? live : live.filter(formule => !formule.removed);
}

// Les jours d'un palier de tarif, ecrits comme le gerant les lit. Une plage
// continue se dit « Mercredi a jeudi » ; des jours epars se listent. La semaine
// commence LUNDI ici (l'ordre du calendrier belge), pas dimanche comme dans
// l'index JavaScript.
const PRICING_DAY_NAMES = ['Dimanche', 'Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi'];
function describePricingDays(days) {
  const list = Array.from(new Set((Array.isArray(days) ? days : [])
    .map(value => Math.trunc(Number(value)))
    .filter(value => Number.isFinite(value) && value >= 0 && value <= 6)));
  if (!list.length) return 'Tous les jours';
  if (list.length === 7) return 'Tous les jours';
  const weekOrder = value => (value === 0 ? 6 : value - 1);
  list.sort((a, b) => weekOrder(a) - weekOrder(b));
  const contiguous = list.every((value, index) => index === 0 || weekOrder(value) === weekOrder(list[index - 1]) + 1);
  if (list.length > 2 && contiguous) {
    return `${PRICING_DAY_NAMES[list[0]]} à ${PRICING_DAY_NAMES[list[list.length - 1]].toLowerCase()}`;
  }
  const names = list.map(value => PRICING_DAY_NAMES[value]);
  if (names.length === 1) return names[0];
  return `${names.slice(0, -1).join(', ')} et ${names[names.length - 1].toLowerCase()}`;
}

function getPricingRows() {
  const usage = getPricingUsageMap();
  const decorate = row => ({
    ...row,
    asset: getPricingAsset(row.type),
    tone: getPricingTone(row.type),
    ...(usage.get(row.id) || { count: 0, players: 0, revenue: 0 })
  });
  // ---- CE CENTRE VEND-IL VRAIMENT CA, ET COMMENT ? ------------------------
  //
  // Ces deux blocs etaient construits depuis les constantes du SOCLE
  // (DURATION_OPTIONS : 20/39/59/78 EUR la piste, LASER_GAME_OPTIONS :
  // 10/18/25 EUR), quel que soit le centre. C'est la grille de Fun Galaxy.
  // Mesure du 2026-08-21 (capture Movsar) : N4, qui n'a AUCUNE arene laser
  // (weaponCount 0) et vend son bowling AUX PARTIES ET PAR PERSONNE, se
  // voyait proposer les quatre durees par piste ET les trois offres laser.
  //
  // Meme regle que les onglets de la page Planning : la CLE ABSENTE veut dire
  // « on ne sait pas encore » (le repli neutre de getAdminCenter rend
  // `resources: {}`) et on n'enleve rien ; la cle PRESENTE a null ou a zero
  // dit que la ressource n'existe pas.
  const centerResources = (typeof getAdminCenter === 'function' ? (getAdminCenter() || {}).resources : null) || {};
  const knowsResource = kind => Object.prototype.hasOwnProperty.call(centerResources, kind);
  const centerLaneCount = Number(centerResources.bowling && centerResources.bowling.laneCount) || 0;
  const centerWeaponCount = Number(centerResources.laser && centerResources.laser.weaponCount) || 0;
  const sellsBowling = !knowsResource('bowling') || centerLaneCount > 0;
  const sellsLaser = !knowsResource('laser') || centerWeaponCount > 0;
  // Le tarif bowling DU CENTRE : present, il vend aux parties et par personne
  // (N4) ; absent, il vend a la grille par piste et par duree (Fun Galaxy).
  // Meme lecture que lib/booking-config.resolveBowlingPricing.
  const bowlingPricing = centerResources.bowling && centerResources.bowling.pricing
    && centerResources.bowling.pricing.mode === 'per_game_per_person'
    && Array.isArray(centerResources.bowling.pricing.tiers)
    && centerResources.bowling.pricing.tiers.length
    ? centerResources.bowling.pricing
    : null;
  const maxPerLane = knowsResource('bowling') && Number(centerResources.bowling && centerResources.bowling.normalCapacityPerLane) > 0
    ? Number(centerResources.bowling.normalCapacityPerLane)
    : MAX_PER_LANE;
  // Une carte par PALIER DE JOURS et par nombre de parties : c'est la forme
  // exacte de la donnee (tiers[].prices[i] = i+1 parties). Afficher un seul
  // prix moyen mentirait, et le gerant ne pourrait plus verifier son tarif.
  const bowlingGameCards = () => {
    const rows = [];
    (bowlingPricing.tiers || []).forEach((tier, tierIndex) => {
      const daysLabel = describePricingDays(tier.days);
      (tier.prices || []).forEach((price, index) => {
        const games = index + 1;
        const gamesLabel = games === 1 ? '1 partie' : `${games} parties`;
        rows.push(decorate({
          id: `bowling-game-${tierIndex}-${games}`,
          type: 'bowling',
          title: `Bowling ${gamesLabel}`,
          subtitle: daysLabel,
          description: `${gamesLabel} par personne, ${daysLabel.toLowerCase()}.`,
          price: Number(price),
          priceUnit: '/pers',
          durationLabel: gamesLabel,
          capacity: `${maxPerLane} joueurs / piste`,
          availability: daysLabel,
          tags: ['Piste', gamesLabel, daysLabel],
          activities: ['Bowling']
        }));
      });
    });
    return rows;
  };
  const bowlingGridCards = () => getDurationOptionsCatalog().map(option => decorate({
    id: `bowling-${Number(option.value)}`,
    type: 'bowling',
    title: `Bowling ${option.label}`,
    subtitle: 'Location de piste',
    description: `${option.label} de jeu, prix par piste, jusqu'à ${maxPerLane} joueurs confort.`,
    price: option.price,
    priceUnit: '/piste',
    durationLabel: option.label,
    capacity: `${maxPerLane} joueurs / piste`,
    availability: 'Selon horaires du centre',
    tags: ['Piste', option.label, `${maxPerLane} joueurs`],
    activities: ['Bowling']
  }));
  const bowling = !sellsBowling ? [] : (bowlingPricing ? bowlingGameCards() : bowlingGridCards());
  // L arene DU CENTRE : 20 armes et six lancements a Gembloux, 30 et un seul
  // a Libramont. La constante disait 30 et 1 partout.
  const armes = getAvailabilityLaserCapacity();
  const lancements = getAvailabilityLaserParallelLaunches();
  const laser = !sellsLaser ? [] : getLaserOptionsCatalog().map(option => decorate({
    id: `laser-${option.games}`,
    type: 'laser',
    title: `${option.label} Laser Game`,
    subtitle: `${option.games} passage${option.games > 1 ? 's' : ''}`,
    description: `${option.durationMinutes} min estimées, session partageable selon l'affluence, ${armes} armes disponibles.`,
    price: option.price,
    durationLabel: `${option.durationMinutes} min`,
    capacity: `${armes} joueurs en même temps au plus`,
    availability: `${lancements} lancement${lancements > 1 ? 's' : ''} simultané${lancements > 1 ? 's' : ''}`,
    tags: ['Laser', `${option.games} partie${option.games > 1 ? 's' : ''}`, `${armes} armes`],
    activities: ['Laser Game']
  }));
  const formulas = getConsoleFormuleCatalog({ includeRemoved: true }).map(formule => {
    const special = formule.family !== 'Formules anniversaires';
    return decorate({
      id: `formula-${formule.id}`,
      sourceId: formule.id,
      removed: formule.removed === true,
      source: formule.source || 'seed',
      family: formule.family || '',
      type: special ? 'special' : 'formula',
      title: formule.name,
      subtitle: formule.family || 'Formule',
      description: (formule.desc || []).join(' · '),
      price: formule.price,
      oldPrice: formule.oldPrice,
      priceType: formule.type,
      durationLabel: `${formatDurationLabel(getFormuleTotalDuration(formule))} estimées`,
      capacity: `${formule.minPax || 1}+ personne${Number(formule.minPax || 1) > 1 ? 's' : ''}`,
      availability: getFormulaAvailabilityLabel(formule),
      tags: [
        formule.hasBowling ? `Bowling ${formatDurationLabel(formule.bowlingDur || 1)}` : '',
        getFormulaLaserGameCount(formule) ? `Laser x${getFormulaLaserGameCount(formule)}` : '',
        formule.noHolidays ? 'Hors congés' : '',
        ...(formule.validDays ? ['Jour limité'] : [])
      ].filter(Boolean),
      activities: formule.desc || [],
      best: !!formule.best,
      notes: formule.notes || []
    });
  });
  return [...bowling, ...laser, ...formulas];
}

function getFormulaAvailabilityLabel(formule) {
  const days = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
  const parts = [];
  if (Array.isArray(formule.validDays) && formule.validDays.length) {
    parts.push(formule.validDays.map(day => days[day] || '').filter(Boolean).join(', '));
  }
  if (formule.timeLimit?.min || formule.timeLimit?.max) {
    parts.push(`${formule.timeLimit.min ? formatClockDisplay(formule.timeLimit.min) : 'ouverture'} - ${formule.timeLimit.max ? formatClockDisplay(formule.timeLimit.max) : 'fermeture'}`);
  }
  if (formule.noHolidays) parts.push('hors vacances/jours fériés');
  return parts.length ? parts.join(' · ') : 'Tous horaires compatibles';
}

// Ce que Copier et Exporter emportent : la recherche de la page s applique.
function getPricingRowsFiltered() {
  const query = String(state.staffPricingQuery || '').trim().toLowerCase();
  const filtered = getPricingRows().filter(row => {
    if (!query) return true;
    return `${row.title} ${row.subtitle} ${row.description} ${row.tags.join(' ')}`.toLowerCase().includes(query);
  });
  return sortPricingRows(filtered);
}

// Classement rentabilité/demande : agrégats réels des réservations (count,
// revenue, players déjà portés par chaque ligne du catalogue).
function sortPricingRows(rows) {
  const ranking = state.staffPricingSort || 'default';
  if (ranking === 'default') return rows;
  const basket = row => (Number(row.count) ? Number(row.revenue || 0) / Number(row.count) : 0);
  const keyFn = {
    demand: row => Number(row.count || 0),
    revenue: row => Number(row.revenue || 0),
    players: row => Number(row.players || 0),
    basket,
  }[ranking] || (row => 0);
  return [...rows].sort((a, b) => keyFn(b) - keyFn(a) || Number(b.revenue || 0) - Number(a.revenue || 0));
}

function setStaffPricingSort(ranking) {
  state.staffPricingSort = state.staffPricingSort === ranking ? 'default' : ranking;
  save();
  renderStaffPricingPage();
}

function getPricingMetrics(rows = getPricingRows()) {
  const revenue = rows.reduce((sum, row) => sum + Number(row.revenue || 0), 0);
  const reservations = rows.reduce((sum, row) => sum + Number(row.count || 0), 0);
  const formulaRows = rows.filter(row => row.type === 'formula' || row.type === 'special');
  const activeOffers = rows.length;
  const topRow = [...rows].sort((a, b) => Number(b.count || 0) - Number(a.count || 0))[0] || null;
  return { revenue, reservations, activeOffers, formulaRows: formulaRows.length, topRow };
}

function setStaffPricingQuery(value) {
  state.staffPricingQuery = value || '';
  renderStaffPricingPage();
}

// C14 : utilitaires d'export partagés staff/direction, vivaient dans
// admin-console.js, désormais ici car ce fichier est chargé pour tous les
// profils alors que la console admin est injectée à la demande.
function downloadTextFile(filename, content, mime = 'text/plain;charset=utf-8') {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function csvCell(value) {
  const text = String(value ?? '');
  return `"${text.replace(/"/g, '""')}"`;
}

// C14 : sélection d'onglet admin sûre même pendant l'injection des consoles 
// l'onglet est mémorisé et setView('admin') le rend une fois le script chargé.
function openAdminTab(tab) {
  if (typeof setAdminTab === 'function') {
    setAdminTab(tab);
    return;
  }
  state.adminTab = tab || 'overview';
  save();
}

// C14 : sélection de centre sûre pendant l'injection, le centre est mémorisé
// et le .then() de setView('admin') rend le dashboard avec (sans ce garde, le
// premier switch de centre était perdu, setAdminCenter n'existant pas encore).
function openAdminCenter(centerId) {
  if (typeof setAdminCenter === 'function') {
    setAdminCenter(centerId);
    return;
  }
  state.adminCenterId = centerId || 'libramont';
  save();
}

// ---- GARDES DE PERMISSION COTE ECRAN (2026-08-19) ---------------------------
// Six permissions etaient DECORATIVES : declarees, affichees dans l editeur de
// roles, et ne gardant rien (audit scripts/permissions-audit-check.js). Les
// decocher ne changeait rien, et pire : le bouton restait la pour mener a un
// refus serveur. Cette garde les rend vraies. Elle vit DANS les fonctions, pas
// seulement sur les boutons : un bouton masque ne protege pas une fonction qui
// reste appelable. Le serveur reste la seule autorite, ceci evite le refus.
function requireClientPermission(permission, message) {
  if (typeof canUseStaffPermission !== 'function' || canUseStaffPermission(permission)) return true;
  if (typeof toast === 'function') toast(message || 'Votre rôle ne permet pas cette action.');
  return false;
}

// 'planning.past' nommait « Modifier une date passee » sans rien garder : la
// restriction n'existait pas. Elle existe desormais, et elle porte sur l'ACTE
// (ecrire sur un jour deja passe), pas sur la lecture : consulter l'historique
// reste ouvert a qui voit le planning.
function requirePastDatePermission(dateStr) {
  const date = String(dateStr || '').slice(0, 10);
  if (!date || typeof isPastBusinessDate !== 'function' || !isPastBusinessDate(date)) return true;
  return requireClientPermission('planning.past', 'Votre rôle ne permet pas de modifier une date passée.');
}

// 'payments.view' nommait « Voir les montants » sans rien masquer. Les surfaces
// de caisse passent par ici : sans le droit, le chiffre cede la place a un
// tiret, jamais a un zero (un zero est un FAIT, et il serait faux).
function moneyForRole(amount) {
  if (typeof canUseStaffPermission === 'function' && !canUseStaffPermission('payments.view')) return '···';
  return typeof formatMoney === 'function' ? formatMoney(amount) : String(amount);
}

// LES GESTES ET LEURS DROITS, EN UN SEUL ENDROIT (2026-11-07, Ansar : « si il
// a pas accès il peut pas voir, sans que ça bug »). Un geste que le serveur
// refuserait ne se montre pas : chaque ligne redit la regle du serveur pour ce
// geste, et chaque bouton de la console la lit avant de se dessiner. Le serveur
// reste l autorite ; scripts/equipe-acces-check.js compare les deux.
//   reserver    POST api/staff-reservations (reservations.create), depuis « Les séances » (reservations.quick)
//   deplacer    PATCH activityMove : planning.drag ou reservations.edit ; un jour passe, planning.past
//   etat        PATCH statut seul : reservations.status ou reservations.edit
//   valider     la demande internet : reservations.edit ; un jour passe, planning.past
//   encaisser   PATCH paye : etat, et payments.markPaid
//   modifier    PATCH du dossier : reservations.edit ; un jour passe, planning.past
//   annuler     PATCH du dossier annule : reservations.edit et reservations.cancel ; un jour passe, planning.past
//   supprimer   DELETE : reservations.cancel ; un jour passe, planning.past
//   retard      delayApply, delayRevert (api/ops.js) : reservations.edit ou planning.drag
//   prevenir    delayNotify : emails.send ou reservations.edit
//   fermerPiste PATCH api/staff-lanes : planning.drag ou settings.manage
//   ecrire      clientMessageSend, sendDirectEmail : emails.send (le composeur lit emails.view)
//   exporter    un fichier de clients ou de chiffres : exports.download
//   noterClient clientNotes, api/staff-customer-notes : clients.edit
const GESTES_STAFF = {
  reserver: (peut) => peut('reservations.quick') && peut('reservations.create'),
  deplacer: (peut, jour) => peut(['planning.drag', 'reservations.edit']) && jour(),
  etat: (peut) => peut(['reservations.status', 'reservations.edit']),
  valider: (peut, jour) => peut('reservations.edit') && jour(),
  encaisser: (peut) => peut(['reservations.status', 'reservations.edit']) && peut('payments.markPaid'),
  modifier: (peut, jour) => peut('reservations.edit') && jour(),
  annuler: (peut, jour) => peut('reservations.edit') && peut('reservations.cancel') && jour(),
  supprimer: (peut, jour) => peut('reservations.cancel') && jour(),
  retard: (peut) => peut(['reservations.edit', 'planning.drag']),
  prevenir: (peut) => peut(['emails.send', 'reservations.edit']),
  fermerPiste: (peut) => peut(['planning.drag', 'settings.manage']),
  // (le meme droit que le serveur, api/ops.js getRequiredOpsPermission : qui modifie les reservations)
  privatiser: (peut) => peut(['reservations.edit', 'settings.manage']),
  ecrire: (peut) => peut('emails.view') && peut('emails.send'),
  exporter: (peut) => peut('exports.download'),
  noterClient: (peut) => peut('clients.edit'),
};

// peutGeste('deplacer', '2026-11-06') : vrai si le role peut faire ce geste, ce
// jour-la (la date ne compte que pour les gestes qui corrigent un dossier).
// Hors console (un gate qui evalue une fonction dans un bac a sable), tout est
// permis, comme requireClientPermission.
function peutGeste(nom, date) {
  const regle = GESTES_STAFF[nom];
  if (!regle) return false;
  if (typeof canUseStaffPermission !== 'function') return true;
  const jourVise = String((date && typeof date === 'object' ? date.date : date) || '').slice(0, 10);
  const jour = () => !jourVise || typeof isPastBusinessDate !== 'function' || !isPastBusinessDate(jourVise) || canUseStaffPermission('planning.past');
  return Boolean(regle(canUseStaffPermission, jour));
}
window.peutGeste = peutGeste;

function exportStaffPricingCsv() {
  if (!requireClientPermission('exports.download', 'Votre rôle ne permet pas de télécharger les exports.')) return;
  const rows = getPricingRowsFiltered();
  const header = ['Type', 'Nom', 'Prix', 'Capacité', 'Disponibilité', 'Réservations (30 j)', 'Joueurs (30 j)', 'Chiffre (30 j)', 'Détails'];
  const body = rows.map(row => [
    getPricingTypeLabel(row.type),
    row.title,
    getPricingPriceLabel(row),
    row.capacity,
    row.availability,
    row.count || 0,
    row.players || 0,
    row.revenue || 0,
    row.description
  ].map(csvCell).join(','));
  downloadTextFile(`${getCurrentStaffCenterId()}-tarifs-formules-${state.currentDate || todayStr()}.csv`, [header.map(csvCell).join(','), ...body].join('\n'), 'text/csv;charset=utf-8');
}

function copyStaffPricingSummary() {
  const rows = getPricingRowsFiltered();
  const summary = rows.map(row => `${row.title}: ${getPricingPriceLabel(row)} (${row.availability})`).join('\n');
  navigator.clipboard?.writeText(summary).then(() => toast('Tarifs copiés.')).catch(() => toast(summary));
}

function getStaffEmailId(item, index = 0) {
  return String(item.id || item.communicationId || item.queueId || [
    item.templateId || 'mail',
    item.recipient || 'recipient',
    item.createdAt || item.scheduledAt || 'time',
    index
  ].join(':'));
}

function getStaffEmailStatusKind(item = {}) {
  const status = String(item.status || 'draft').toLowerCase();
  if (status === 'sent' || status === 'delivered') return 'sent';
  if (status === 'failed' || status === 'error') return 'failed';
  if (status === 'queued' || status === 'pending') return 'queued';
  if (status === 'skipped') return 'paused';
  return 'draft';
}

function getStaffEmailStatusLabel(item = {}) {
  const kind = getStaffEmailStatusKind(item);
  const labels = {
    sent: 'Envoyé',
    failed: 'À corriger',
    queued: 'En file',
    paused: 'En pause',
    draft: 'Brouillon'
  };
  return labels[kind] || 'Message';
}

function getStaffEmailRows() {
  // C14 : ops-console.js est injecté à la demande, avant son arrivée, la page
  // Emails rend son état vide (le chargement est déjà déclenché par la page).
  if (typeof getVisibleOpsCommunications !== 'function') return [];
  return getVisibleOpsCommunications()
    .map((item, index) => ({
      ...item,
      uid: getStaffEmailId(item, index),
      sourceIndex: index,
      statusKind: getStaffEmailStatusKind(item),
      templateLabel: getOpsTemplateLabel(item.templateId)
    }));
}

// ── Origine d'une communication : QUI l'a déclenchée ─────────────────────────
// Classifieur ancré sur les champs payload RÉELLEMENT posés par chaque chemin
// d'envoi serveur (vérifiés un à un sur les enqueue de lib/ops-communications.js,
// lib/ops-jobs.js et lib/email-agent.js) :
//   'inbound' : mail REÇU (ingestInboundEmail : direction='inbound', status
//               'received'). Ni auto ni manuel : c'est le client qui écrit.
//   'manual'  : une action humaine directe a déclenché CET envoi :
//               payload.direct/directEmail → sendDirectEmail (composer, studio_*)
//               payload.relance            → sendClientRelance (relance 1-clic, relance_*)
//               payload.clientMessage      → sendClientMessage (message depuis une résa, client_*)
//               payload.test               → sendAutomationTest (test au staff connecté, test_*)
//               payload.campaignId         → enqueueCampaign (campagne lancée par l'équipe, campaign_*)
//   'auto'    : tout le reste, parti tout seul (worker/cron/séquences) :
//               request_received, confirmation, reminder_48h, reminder_day_sms,
//               staff_review_request, delay_change, post_visit_followup,
//               birthday_j30, reactivation, custom_* et les rangées de
//               simulation. AUCUN de ces chemins ne pose les flags ci-dessus.
function getStaffEmailOrigin(row = {}) {
  if (row.direction === 'inbound' || row.status === 'received') return 'inbound';
  const payload = row.payload && typeof row.payload === 'object' ? row.payload : {};
  const flag = (value) => value === true || value === 'true';
  if (flag(payload.direct) || flag(payload.directEmail)) return 'manual';
  if (flag(payload.relance)) return 'manual';
  if (flag(payload.clientMessage)) return 'manual';
  if (flag(payload.test)) return 'manual';
  if (payload.campaignId) return 'manual';
  return 'auto';
}

function getStaffEmailOriginLabel(row = {}) {
  const origin = getStaffEmailOrigin(row);
  if (origin === 'inbound') return 'Reçu';
  return origin === 'manual' ? 'Envoi manuel' : 'Automatique';
}

function getStaffEmailText(row = {}) {
  const payload = row.payload || {};
  return [
    row.subject,
    row.recipient,
    row.templateLabel || getOpsTemplateLabel(row.templateId),
    row.channel,
    row.status,
    row.lastError,
    payload.textBody,
    payload.validationMode,
    payload.customerName,
    payload.phone
  ].filter(Boolean).join(' ').toLowerCase();
}

function getStaffEmailRowsFiltered() {
  const filter = state.staffEmailFilter || 'all';
  const template = state.staffEmailTemplateFilter || 'all';
  // Origine (auto/manuel) COMBINABLE avec les statuts : les deux filtres se
  // cumulent (ex. « Envois manuels » + « Échecs »). 'inbound' est géré par la
  // page (pv2EmailFilter), pas ici.
  const origin = ['auto', 'manual'].includes(state.staffEmailOriginFilter) ? state.staffEmailOriginFilter : 'all';
  const query = String(state.staffEmailQuery || '').trim().toLowerCase();
  return getStaffEmailRows().filter(row => {
    if (origin !== 'all' && getStaffEmailOrigin(row) !== origin) return false;
    if (filter === 'review' && row.templateId !== 'staff_review_request') return false;
    if (filter !== 'all' && filter !== 'review' && row.statusKind !== filter) return false;
    if (template !== 'all' && row.templateId !== template) return false;
    if (query && !getStaffEmailText(row).includes(query)) return false;
    return true;
  });
}

function getStaffEmailMetrics(rows = getStaffEmailRows()) {
  const sent = rows.filter(row => row.statusKind === 'sent').length;
  const queued = rows.filter(row => row.statusKind === 'queued').length;
  const failed = rows.filter(row => row.statusKind === 'failed').length;
  const review = rows.filter(row => row.templateId === 'staff_review_request').length;
  const due = rows.filter(row => row.statusKind === 'queued' && (!row.scheduledAt || new Date(row.scheduledAt).getTime() <= Date.now())).length;
  const reminders = rows.filter(row => row.templateId === 'reminder_48h').length;
  const attempted = rows.reduce((sum, row) => sum + Number(row.attempts || 0), 0);
  const deliveryBase = sent + failed;
  // AUCUN ENVOI, AUCUN TAUX. La valeur par defaut etait 100, donc le bandeau
  // affichait « 0 Envoye » surmontant « 100 % de reussite » : un taux de
  // reussite calcule sur rien, qui se lit comme un fait. Un taux sans base
  // n existe pas ; on renvoie l absence, et l affichage n ecrit rien.
  const deliveryRate = deliveryBase ? Math.round((sent / deliveryBase) * 100) : null;
  return { sent, queued, failed, review, due, reminders, attempted, deliveryRate, total: rows.length };
}

function setStaffEmailQuery(query = '') {
  state.staffEmailQuery = String(query || '');
  state.staffEmailSelectedId = '';
  save();
  renderStaffEmailsPage();
}

function getSelectedStaffEmailRow(rows = getStaffEmailRowsFiltered()) {
  if (!rows.length) return null;
  const selected = rows.find(row => row.uid === state.staffEmailSelectedId);
  return selected || rows[0];
}

// `rows` optionnel : la section Envoyés exporte exactement la file qu'elle
// affiche (ses filtres Remis/Ouverts n'existent pas dans le filtre historique).
function exportStaffEmailsCsv(rowsAffichees = null) {
  if (!requireClientPermission('exports.download', 'Votre rôle ne permet pas de télécharger les exports.')) return;
  const rows = Array.isArray(rowsAffichees) ? rowsAffichees : getStaffEmailRowsFiltered();
  const header = ['Statut', 'Origine', 'Modele', 'Sujet', 'Destinataire', 'Canal', 'Planifie', 'Envoye', 'Tentatives', 'Erreur'];
  const body = rows.map(row => [
    getStaffEmailStatusLabel(row),
    getStaffEmailOriginLabel(row),
    getOpsTemplateLabel(row.templateId),
    row.subject || '',
    row.recipient || '',
    row.channel || 'email',
    row.scheduledAt || '',
    row.sentAt || '',
    Number(row.attempts || 0),
    row.lastError || ''
  ].map(csvCell).join(','));
  downloadTextFile(`${getCurrentStaffCenterId()}-mails-${state.currentDate || todayStr()}.csv`, [header.map(csvCell).join(','), ...body].join('\n'), 'text/csv;charset=utf-8');
}

function getStaffClientInitials(name = '') {
  const parts = String(name || 'Client')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2);
  return (parts.map(part => part[0]).join('') || 'CL').toUpperCase();
}

function staffClientJs(value) {
  // escapeHtml sur le littéral JSON : sans ça les guillemets doubles de
  // JSON.stringify cassent l'attribut onclick="..." (double quotes) et le
  // handler devient un no-op silencieux (boutons fantômes Terrain/Groupes).
  // Encodé en entités, l'argument est valable dans onclick="" comme onclick=''.
  return escapeHtml(JSON.stringify(String(value || '')).replace(/</g, '\\u003c'));
}

