function getPlanningVisibleReservations(view = getStaffResourceView()) {
  let reservations = todaysReservations().filter(r => reservationMatchesStaffResource(r, view));
  releaseDeadNoteFilter();
  reservations = filterReservationsForStaff(reservations, state.staffStatusFilter || 'all');
  const query = String(state.searchTerm || '').trim().toLowerCase();
  if (query) {
    const numero = numeroReservationDe(query);
    reservations = reservations.filter(r => {
      if (reservationPorteLeNumero(r, numero)) return true;
      const label = `${r.name || ''} ${r.phone || ''} ${getReservationLabel(r)} ${r.email || ''} ${texteRecherchableDuDossier(r)}`.toLowerCase();
      return label.includes(query);
    });
  }
  return reservations;
}

// CE QUI EST ECRIT SUR LE DOSSIER SE CHERCHE AUSSI (l audit du 2026-11-03 : « pizza »,
// « arachide » ne trouvaient rien) : les notes, les extras, la note de fiche.
function texteRecherchableDuDossier(r) {
  const extras = (Array.isArray(r.extras) ? r.extras : []).map(e => (e && (e.name || e.label)) || '');
  const equipe = getReservationNotesEquipe(r).map(n => n.t);
  const fiche = window.PinlaneStaffNotes && typeof window.PinlaneStaffNotes.text === 'function' ? window.PinlaneStaffNotes.text(r) : '';
  return [getReservationNoteText(r), ...equipe, fiche, ...extras].join(' ');
}

// Recherche planning/liste unifiée. Root cause du bug : les champs de recherche
// n'appelaient que renderTable() : le PLANNING (grille) et le planning Laser ne
// se re-filtraient jamais à la frappe (il fallait recharger), et l'effacement ne
// re-remplissait pas la grille (elle restait figée). On centralise ici : un seul
// state.searchTerm, on synchronise les champs jumeaux (bowling/laser/liste) sans
// voler le focus, puis on re-render planning + planning laser + liste. Débounce
// léger pour rester fluide à la frappe ; effacement = ré-affichage immédiat.
let staffSearchDebounceTimer = null;
// UNE FAUTE LEGERE DANS UN NOM (2026-11-02, audit joue sur la vraie console :
// « mason » ne trouvait pas Masson). Au comptoir on tape ce qu on entend, dans le
// bruit : une lettre en trop, en moins, changee, ou deux lettres inversees ; deux
// fautes pour un mot de 8 lettres et plus. Les textes arrivent sans accents ni
// majuscules. Sous 4 lettres, aucune tolerance : « Léa » ressemblerait a tout. Le
// tableau et la page Réservations n y viennent que si rien d exact n existe.
function distanceNoms(a, b, plafond) {
  if (Math.abs(a.length - b.length) > plafond) return plafond + 1;
  let avantDerniere = null;
  let derniere = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i += 1) {
    const ligne = [i];
    for (let j = 1; j <= b.length; j += 1) {
      const cout = a[i - 1] === b[j - 1] ? 0 : 1;
      let d = Math.min(derniere[j] + 1, ligne[j - 1] + 1, derniere[j - 1] + cout);
      if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) d = Math.min(d, avantDerniere[j - 2] + 1);
      ligne[j] = d;
    }
    avantDerniere = derniere;
    derniere = ligne;
  }
  return derniere[b.length];
}

function nomRessemble(nom, cherche) {
  const decouper = (texte) => String(texte || '').split(/[^\p{L}\p{N}]+/u).filter(Boolean);
  const tolere = (mot) => mot.length >= 4 && /\p{L}/u.test(mot);
  const mots = decouper(nom);
  const voulus = decouper(cherche);
  if (!mots.length || !voulus.some(tolere)) return false;
  return voulus.every((voulu) => {
    const plafond = voulu.length >= 8 ? 2 : 1;
    return mots.some((mot) => mot.includes(voulu) || (tolere(voulu) && distanceNoms(mot, voulu, plafond) <= plafond));
  });
}

// (la croix du champ, sur les trois plannings)
function syncStaffSearchCroix() {
  const croix = document.getElementById('gfEfface');
  if (croix) croix.hidden = !String(state.searchTerm || '').trim();
}

function applyStaffSearch(value, opts = {}) {
  state.searchTerm = value;
  ['searchInput', 'globalPlanningSearchInput'].forEach(id => {
    const el = document.getElementById(id);
    if (el && el !== document.activeElement && el.value !== value) el.value = value;
  });
  syncStaffSearchCroix();
  const run = () => {
    save();
    if (state.view !== 'staff') return;
    // (la ligne sous la barre dit la recherche en cours : pbRechercheHtml)
    renderKpis();
    renderPlanning();
    renderLaserPlanning();
    renderGlobalPlanningSurface();
    avecListeDifferable(renderTable);
  };
  clearTimeout(staffSearchDebounceTimer);
  // Effacer (champ vide) = ré-affichage instantané du planning complet, sans délai.
  if (opts.immediate || !String(value || '').trim()) {
    run();
    return;
  }
  staffSearchDebounceTimer = setTimeout(run, 120);
}

// CE QUE LA RECHERCHE LAISSE NET, pour la ligne qui l explique sous la barre
// (pbRechercheHtml) : les groupes que la grille de la vue dessine, comptes avec
// sa regle. Bowling : recherche et filtre (getPlanningVisibleReservations).
// Laser : la recherche seule (lpChercheur). Le planning complet ne grise rien,
// il range ses resultats et les compte lui-meme.
function rechercheDuPlanning(vue = getStaffResourceView()) {
  const terme = String(state.searchTerm || '').trim();
  if (!terme || (vue !== 'bowling' && vue !== 'laser')) return null;
  const dessines = todaysReservations().filter(tientSesPlaces).filter(r => (vue === 'laser'
    ? getLaserWindowsFromReservation(r).length > 0
    : reservationMatchesStaffResource(r, 'bowling') && getBowlingWindowsFromReservation(r).length > 0));
  let nets;
  if (vue === 'laser') {
    nets = dessines.filter(lpChercheur(terme)).length;
  } else {
    const retenues = new Set(getPlanningVisibleReservations('bowling').map(r => String(r.id)));
    nets = dessines.filter(r => retenues.has(String(r.id))).length;
  }
  return { terme, nets, total: dessines.length };
}

// « TOUT AFFICHER » : la recherche et le filtre s enlevent d un toucher, toute
// la journee revient nette.
function toutAfficherPlanning() {
  const champ = document.getElementById('globalPlanningSearchInput');
  if (champ) champ.value = '';
  state.staffStatusFilter = 'all';
  applyStaffSearch('', { immediate: true });
}

function closeStaffFloatingMenus() {
  document.querySelectorAll('.staff-action-popover').forEach(menu => menu.remove());
}

// LE PETIT MENU SE FERME DES QU ON TOUCHE AILLEURS, MEME LA OU LE CLIC EST ARRETE (2026-11-20).
// Le menu de gauche et le tableau du planning arretent leurs clics (stopPropagation) : le clic
// de fermeture, pose sur document, ne les entendait jamais. Le petit menu d une ligne restait
// ouvert par-dessus la page suivante, et bloquait Entree pour pointer Arrive tant qu il etait la.
// L appui est entendu a la capture, avant tout gestionnaire ; Echap le ferme et rend la main a
// son bouton. Toucher son propre bouton le laisse a la bascule de showStaffFloatingMenu.
document.addEventListener('pointerdown', (event) => {
  const menu = document.querySelector('.staff-action-popover');
  if (!menu || menu.contains(event.target)) return;
  if (menu._ancre && menu._ancre.contains && menu._ancre.contains(event.target)) return;
  closeStaffFloatingMenus();
}, true);
document.addEventListener('keydown', (event) => {
  if (event.key !== 'Escape') return;
  const menu = document.querySelector('.staff-action-popover');
  if (!menu) return;
  event.preventDefault();
  event.stopPropagation();
  const ancre = menu._ancre;
  closeStaffFloatingMenus();
  if (ancre && ancre.isConnected && typeof ancre.focus === 'function') ancre.focus({ preventScroll: true });
}, true);

function showStaffFloatingMenu(event, html) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  const current = document.querySelector('.staff-action-popover');
  if (current && current.dataset.anchor === event?.currentTarget?.className) {
    current.remove();
    return;
  }
  closeStaffFloatingMenus();
  const menu = document.createElement('div');
  menu.className = 'staff-action-popover';
  menu.dataset.anchor = event?.currentTarget?.className || 'staff-action';
  menu._ancre = event?.currentTarget || null;
  menu.innerHTML = html;
  document.body.appendChild(menu);
  const rect = event?.currentTarget?.getBoundingClientRect?.();
  if (rect) {
    const width = Math.min(260, Math.max(menu.offsetWidth || 220, 220));
    const left = Math.min(window.innerWidth - width - 12, Math.max(12, rect.right - width));
    const top = Math.min(window.innerHeight - 12, rect.bottom + 8);
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
  }
  if (window.PlMouvement) window.PlMouvement.surgir(menu, event?.currentTarget);
  setTimeout(() => document.addEventListener('click', closeStaffFloatingMenus, { once: true }), 0);
}

function applyPlanningStatusFilter(filter) {
  state.staffStatusFilter = normaliserFiltreListe(filter);
  save();
  closeStaffFloatingMenus();
  repaintKeepingScroll(document.getElementById('staffView'), () => renderStaff());
}

// LE MÊME FILTRE, DONC LES MÊMES MOTS ET LE MÊME CLASSEMENT QUE LA LISTE.
// Ce menu pilote `state.staffStatusFilter`, exactement comme les puces de la
// liste du jour : il nommait pourtant « Payées » ce que la liste appelle
// « Terminées », et rangeait « À gérer » entre deux états comme s'il en était
// un troisième. Un même filtre qui porte deux noms selon l'endroit où on le
// touche, c'est la même classe d'erreur que les compteurs qui ne se
// recomposent pas. Depuis le 2026-10-08 : les sections de la liste, dans son
// ordre et sous ses mots (STAFF_LISTE_MOTS).
function planningFiltresHtml() {
  const active = normaliserFiltreListe(state.staffStatusFilter);
  const bouton = ([key, label]) => `<button type="button" class="${active === key ? 'active' : ''}" onclick="applyPlanningStatusFilter('${key}')">${label}</button>`;
  const etats = [['all', 'Tout voir'], ...STAFF_LISTE_SECTIONS.map(cle => [cle, STAFF_LISTE_MOTS[cle]])];
  return `
    <div class="staff-action-popover-title">Filtrer le planning</div>
    ${etats.map(bouton).join('')}
  `;
}

